+fn render_html_document(book: &Book, rendered: &RenderedBook) -> String {
+    let title = escape_html(book_title(book));
+    let author = escape_html(book_author(book));
+    let subtitle = book.options.get("subtitle").cloned().unwrap_or_default();
+    let lang = escape_html(book_lang(book));
+    let autograph = book.options.get("autograph").cloned().unwrap_or_default();
+    let has_toc = rendered.toc_entries.len() > 1;
+    let mut out = String::new();
+    let _ = write!(
+        out,
+        "<!DOCTYPE html>\n<html lang=\"{lang}\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"generator\" content=\"crowbook\">\n    <meta name=\"viewport\" content=\"width=device-width\">\n    <meta name=\"author\" content=\"{author}\">\n    \n    <title>{title}</title>\n    <style type = \"text/css\">\n      {HTML_CSS}\n    </style>\n    <style type = \"text/css\" media = \"print\">\n      {HTML_PRINT_CSS}\n    </style>\n   <script>\n{HTML_JS}\n   </script>\n\n\n  </head>\n  <body>\n    {}\n",
+        json_ld(book)
+    );
+    if has_toc {
+        let _ = write!(
+            out,
+            "    <nav id = \"nav\">\n      \n      <div id = \"nav-title\">\n        <h2><a href = \"#link-0\">{title}</a></h2>\n      </div>\n          <ul>\n"
+        );
+        for entry in &rendered.toc_entries {
+            let _ = writeln!(
+                out,
+                "      <li><a href=\"#link-{}\">{}</a></li>",
+                entry.link_id,
+                escape_html(&entry.label)
+            );
+        }
+        out.push_str("    </ul>\n    </nav>\n\n");
+    }
+    out.push_str("    <div id = \"content\">\n      \n      <div id = \"page\">\n        <header>\n\n          <div id = \"menu\">\n");
+    if has_toc {
+        let menu_svg = include_str!("../observed/menu_svg.txt").trim();
+        let _ = write!(
+            out,
+            "\t        \n            <img id = \"menu-button\" onclick=\"toggle();\"\n                 src=\"{menu_svg}\"\n                 alt = \"Table of contents\" title = \"Table of contents\" />\n          \n"
+        );
+    } else {
+        out.push_str("\t        \n");
+    }
+    let _ = write!(
+        out,
+        "          </div>\n\t  <h2 class=\"author\">{author}</h2>\n          <h1 id = \"link-0\" class=\"title\" >{title}</h1>\n"
+    );
+    if !subtitle.is_empty() {
+        let _ = writeln!(
+            out,
+            "\t  <h2 class = \"subtitle\">{}</h2>",
+            escape_html(&subtitle)
+        );
+    } else {
+        out.push_str("\t  \n");
+    }
+    if !autograph.is_empty() {
+        let _ = write!(
+            out,
+            "\t  \n\t  <div id = \"autograph\">\n\t    {}\n\t  </div>\n",
+            escape_html(&autograph)
+        );
+    } else {
+        out.push_str("\t  \n");
+    }
+    out.push_str("\t  \n        </header>\n\n");
+    for file in &rendered.files {
+        out.push_str(&file.body_html);
+        out.push('\n');
+    }
+    out.push_str("\n      </div>\n      \n    </div>\n  </body>\n</html>\n");
+    out
+}
