+fn render_tex_document(book: &Book) -> String {
+    let lang = tex_lang(book_lang(book));
+    let title = escape_tex(book_title(book));
+    let author = escape_tex(book_author(book));
+    let mut body = String::new();
+    for chapter in &book.chapters {
+        let raw_html = render_markdown_html(&chapter.content);
+        let plain = plain_text_from_html(&raw_html);
+        let first_title = first_visible_title(&raw_html);
+        let content = if let Some(pos) = plain.find(&first_title) {
+            plain[pos + first_title.len()..].trim().to_string()
+        } else {
+            plain.trim().to_string()
+        };
+        if !first_title.is_empty() {
+            let _ = writeln!(body, "\\chapter{{{}}}", escape_tex(&first_title));
+            let _ = writeln!(body, "\\label{{chapter-{}}}", body.matches("\\chapter{").count() - 1);
+        }
+        if !content.is_empty() {
+            let _ = writeln!(body, "{}", escape_tex(&content));
+            let _ = writeln!(body);
+        }
+    }
+    format!(
+        "\\documentclass{{book}}\n\n%% Package inclusion\n\n% Unicode support if xelatex is used\n\\usepackage{{fontspec}}\n\\usepackage{{xunicode}}\n\n\n\\usepackage[{lang}]{{babel}} % Language support\n\\usepackage{{fancyhdr}} % Headers\n\\usepackage{{enumitem}}\n\n% Allows hyphenatations in \\texttt\n\\usepackage[htt]{{hyphenat}}\n\n\n\n% Set hyperlinks and metadata\n\\usepackage[colorlinks=true,breaklinks=true,hypertexnames=false]{{hyperref}}\n\\hypersetup{{pdfauthor={{{author}}},\n  pdftitle={{{title}}},\n  pdfsubject={{}}\n}}\n\n\n\n\n\n\n% Included if the stdpage option if set to false\n\\usepackage[a5paper, top=2cm, bottom=1.5cm,\n  left=2.5cm,right=1.5cm]{{geometry}} % Set dimensions/margins of the page\n\n\n\n\n\n\\makeatletter\n\\date{{}}\n\n\n  \n% Redefine the \\maketitle command, only for book class (not used if stdpage option is set to true)\n\\renewcommand{{\\maketitle}}{{\n  \n\n  % First page with only the title\n  \\thispagestyle{{empty}}\n  \\vspace*{{\\stretch{{1}}}}\n\n  \\begin{{center}}\n    {{\\Huge \\@title   \\\\[5mm]}}\n  \\end{{center}}\n  \\vspace*{{\\stretch{{2}}}}\n\n  \\newpage\n  % Empty left page\n  \\thispagestyle{{empty}}\n  \\cleardoublepage\n\n  % Main title page, with author, title, subtitle, date\n  \\begin{{center}}\n    \\thispagestyle{{empty}}\n    \\vspace*{{\\baselineskip}}\n    \\rule{{\\textwidth}}{{1.6pt}}\\vspace*{{-\\baselineskip}}\\vspace*{{2pt}}\n    \\rule{{\\textwidth}}{{0.4pt}}\\\\[\\baselineskip]\n\n    {{\\Huge\\scshape \\@title   \\\\[5mm]}}\n    {{\\Large }}\n\n    \\rule{{\\textwidth}}{{0.4pt}}\\vspace*{{-\\baselineskip}}\\vspace{{3.2pt}}\n    \\rule{{\\textwidth}}{{1.6pt}}\\\\[\\baselineskip]\n\n    \\vspace*{{4\\baselineskip}}\n\n    {{\\Large \\@author}}\n      \n    \\vfill\n      \n  \\end{{center}}\n\n  \\pagebreak\n  \\newpage\n  % Copyright page with author, version, and license\n  \\thispagestyle{{empty}}\n  \\null\\vfill\n  \\noindent\n  \\begin{{center}}\n    {{\\emph{{\\@title}}.\\\\[5mm]}}\n    \n  \\end{{center}}\n  \\pagebreak\n  \\newpage\n}}\n  \n\n\n% Redefine headers\n\\pagestyle{{fancy}}\n\\fancyhead{{}}\n\\fancyhead[CO,CE]{{\\thepage}}\n\\fancyfoot{{}}\n\n\n\n\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\n% Command and environment definitions\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\n\n% Strong\n\\newcommand\\mdstrong[1]{{\\textbf{{#1}}}}\n\n% Code\n\\newcommand\\mdcode[1]{{\\texttt{{#1}}}}\n\n% Rule\n\\newcommand\\mdrule{{\n  \\nopagebreak\n  {{\\vskip 1em}}\n  \\nopagebreak\n  \\begin{{center}}\n    ***\n  \\end{{center}}\n  \\nopagebreak\n {{\\vskip 1em}}\n \\nopagebreak\n}}\n\n% Hardbreak\n\\newcommand\\mdhardbreak{{\\\\}}\n\n% Block quote$\n\\newenvironment{{mdblockquote}}{{%\n  \\begin{{quotation}}\n    \\itshape\n}}{{%\n  \\end{{quotation}}\n}}\n\n\n% Code block\n\\makeatother\n\n\\title{{{title}}}\n\\author{{{author}}}\n\n\\begin{{document}}\n\n% Redefine chapter and part names if they needs to be\n% Needs to be after \\begin{{document}} because babel\n\n\n\n\n\n\\maketitle\n\n\n\n\n{body}\n\n\\end{{document}}\n"
+    )
+}
