+fn render_epub_bytes(book: &Book, rendered: &RenderedBook) -> Result<(Vec<u8>, Vec<Diagnostic>), Vec<Diagnostic>> {
+    let mut diagnostics = Vec::new();
+    if Command::new("zip").arg("-h").output().is_err() {
+        diagnostics.push(Diagnostic {
+            level: Level::Warning,
+            text: EPUB_WARNING.to_string(),
+            detailed: None,
+        });
+    }
+    let version = book
+        .options
+        .get("epub.version")
+        .and_then(|v| v.parse::<u32>().ok())
+        .unwrap_or(2);
+
+    let mut bytes = Vec::new();
+    let cursor = std::io::Cursor::new(&mut bytes);
+    let mut zip = zip::ZipWriter::new(cursor);
+    let stored = FileOptions::default().compression_method(CompressionMethod::Stored);
+    let deflated = FileOptions::default().compression_method(CompressionMethod::Deflated);
+
+    zip.start_file("mimetype", stored).ok();
+    zip.write_all(b"application/epub+zip").ok();
+
+    zip.start_file("META-INF/container.xml", deflated).ok();
+    zip.write_all(container_xml().as_bytes()).ok();
+    zip.start_file("META-INF/com.apple.ibooks.display-options.xml", deflated)
+        .ok();
+    zip.write_all(ibooks_display_options().as_bytes()).ok();
+
+    zip.start_file("OEBPS/title_page.xhtml", deflated).ok();
+    zip.write_all(epub_title_page(book, version).as_bytes()).ok();
+
+    for (index, file) in rendered.files.iter().enumerate() {
+        zip.start_file(format!("OEBPS/chapter_{index:03}.xhtml"), deflated)
+            .ok();
+        zip.write_all(epub_chapter_page(book, file, index, version).as_bytes())
+            .ok();
+    }
+
+    zip.start_file("OEBPS/stylesheet.css", deflated).ok();
+    zip.write_all(EPUB_CSS.as_bytes()).ok();
+    zip.start_file("OEBPS/content.opf", deflated).ok();
+    zip.write_all(epub_content_opf(book, rendered, version).as_bytes()).ok();
+    zip.start_file("OEBPS/toc.ncx", deflated).ok();
+    zip.write_all(epub_toc_ncx(rendered).as_bytes()).ok();
+    zip.start_file("OEBPS/nav.xhtml", deflated).ok();
+    zip.write_all(epub_nav(book, rendered, version).as_bytes()).ok();
+    let _ = zip.finish();
+
+    Ok((bytes, diagnostics))
+}
+
