use std::collections::{BTreeMap, BTreeSet};
use std::env;
use std::fmt::Write as _;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};

use pulldown_cmark::{html, Options, Parser};
use zip::write::FileOptions;
use zip::CompressionMethod;

const VERSION: &str = "crowbook 0.17.0";
const BANNER: &str = "CROWBOOK 0.17.0";
const HELP_TEXT: &str = include_str!("../observed/help.txt");
const LIST_OPTIONS_TEXT: &str = include_str!("../observed/list_options.txt");
const HTML_CSS: &str = include_str!("../observed/templates/html.css.txt");
const HTML_PRINT_CSS: &str = include_str!("../observed/templates/html.css.print.txt");
const HTML_JS: &str = include_str!("../observed/templates/html.js.txt");
const HTML_STANDALONE_TEMPLATE: &str =
    include_str!("../observed/templates/html.standalone.template.txt");
const HTML_DIR_TEMPLATE: &str = include_str!("../observed/templates/html.dir.template.txt");
const EPUB_CSS: &str = include_str!("../observed/templates/epub.css.txt");
const EPUB_CHAPTER_TEMPLATE: &str =
    include_str!("../observed/templates/epub.chapter.xhtml.txt");
const EPUB_TITLEPAGE_TEMPLATE: &str =
    include_str!("../observed/templates/epub.titlepage.xhtml.txt");
const TEX_TEMPLATE: &str = include_str!("../observed/templates/tex.template.txt");
const CREATE_TEMPLATE_HEAD: &str = "\"author: Your name\"\n\"title: Your title\"\n\"lang: en\"\n\n\"## Output formats\"\n\n\"# Uncomment and fill to generate files\"\n\"# output.html: some_file.html\"\n\"# output.epub: some_file.epub\"\n\"# output.pdf: some_file.pdf\"\n\n\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"\n\"# output: [pdf, epub, html]\"\n\n\"# Uncomment and fill to set cover image (for EPUB)\"\n\"# cover: some_cover.png\"\n\n## List of chapters\n";
const HTML_DIR_TEMPLATE_ERROR: &str = "Error compiling template: render error\n\n  --> <anonymous>:8:7\n   |\n 8 |     {{favicon}}\n   |       ^^^^^^^\n   |\n   = reason: not found in this scope";
const EPUB_WARNING: &str = "Could not run zip command, falling back to zip library";
const PDF_COMMAND_ERROR: &str = "Error during temporary files editing: failed to run command 'xelatex'";

#[derive(Debug, Default)]
struct Cli {
    force_emoji: bool,
    single: bool,
    no_fancy: bool,
    verbose: bool,
    autograph: bool,
    quiet: bool,
    create: Option<Vec<String>>,
    output: Option<String>,
    to: Option<String>,
    set_values: Vec<String>,
    list_options: bool,
    runtime_lang: Option<String>,
    print_template: Option<String>,
    stats: bool,
    help: bool,
    version: bool,
    book: Option<String>,
}

#[derive(Clone)]
struct ChapterSource {
    source_name: String,
    content: String,
}

#[derive(Default, Clone)]
struct Book {
    source_path: PathBuf,
    base_dir: PathBuf,
    options: BTreeMap<String, String>,
    chapters: Vec<ChapterSource>,
}

#[derive(Clone, Default)]
struct HtmlChapterFile {
    source_name: String,
    title: String,
    body_html: String,
}

#[derive(Clone)]
struct TocEntry {
    link_id: usize,
    label: String,
}

#[derive(Default)]
struct RenderState {
    next_link_id: usize,
    next_para_id: usize,
    next_chapter_number: usize,
}

#[derive(Default)]
struct RenderedBook {
    files: Vec<HtmlChapterFile>,
    toc_entries: Vec<TocEntry>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Target {
    Html,
    Epub,
    Pdf,
    Tex,
    Odt,
    HtmlDir,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Level {
    Warning,
    Error,
}

#[derive(Clone)]
struct Diagnostic {
    level: Level,
    text: String,
    detailed: Option<String>,
}

enum ParseErrorKind {
    MissingValue { display: &'static str },
    TwoValuesRequired,
    UnexpectedArg { arg: String, tip: bool },
    MissingToForOutput,
    InvalidTo(String),
}

fn main() {
    let args: Vec<String> = env::args().collect();
    match parse_args(&args) {
        Ok(cli) => {
            let code = run(cli);
            std::process::exit(code);
        }
        Err(kind) => {
            eprint!("{}", format_parse_error(kind));
            std::process::exit(2);
        }
    }
}

fn parse_args(args: &[String]) -> Result<Cli, ParseErrorKind> {
    let mut cli = Cli::default();
    let mut i = 1usize;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" {
            i += 1;
            while i < args.len() {
                push_positional(&mut cli, args[i].clone())?;
                i += 1;
            }
            break;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            match rest {
                "force-emoji" => cli.force_emoji = true,
                "single" => cli.single = true,
                "no-fancy" => cli.no_fancy = true,
                "verbose" => cli.verbose = true,
                "autograph" => cli.autograph = true,
                "quiet" => cli.quiet = true,
                "list-options" => cli.list_options = true,
                "stats" => cli.stats = true,
                "help" => cli.help = true,
                "version" => cli.version = true,
                "create" => {
                    let (values, next) = collect_multi_values(args, i + 1);
                    if values.is_empty() {
                        return Err(ParseErrorKind::MissingValue {
                            display: "--create <files>...",
                        });
                    }
                    cli.create = Some(values);
                    i = next;
                    continue;
                }
                "set" => {
                    let (values, next) = collect_multi_values(args, i + 1);
                    if values.is_empty() {
                        return Err(ParseErrorKind::MissingValue {
                            display: "--set <set> <set>...",
                        });
                    }
                    if values.len() == 1 {
                        return Err(ParseErrorKind::TwoValuesRequired);
                    }
                    cli.set_values.extend(values);
                    i = next;
                    continue;
                }
                "output" => {
                    cli.output = Some(expect_value(args, i + 1, "--output <output>")?);
                    i += 1;
                }
                "to" => {
                    let value = expect_value(args, i + 1, "--to <to>")?;
                    if !is_valid_to(&value) {
                        return Err(ParseErrorKind::InvalidTo(value));
                    }
                    cli.to = Some(value);
                    i += 1;
                }
                "lang" => {
                    cli.runtime_lang = Some(expect_value(args, i + 1, "--lang <lang>")?);
                    i += 1;
                }
                "print-template" => {
                    cli.print_template =
                        Some(expect_value(args, i + 1, "--print-template <print-template>")?);
                    i += 1;
                }
                _ => {
                    return Err(ParseErrorKind::UnexpectedArg {
                        arg: arg.clone(),
                        tip: true,
                    });
                }
            }
            i += 1;
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 {
            let chars: Vec<char> = arg.chars().collect();
            let mut j = 1usize;
            while j < chars.len() {
                let ch = chars[j];
                match ch {
                    'f' => cli.force_emoji = true,
                    's' => cli.single = true,
                    'n' => cli.no_fancy = true,
                    'v' => cli.verbose = true,
                    'a' => cli.autograph = true,
                    'q' => cli.quiet = true,
                    'l' => cli.list_options = true,
                    'S' => cli.stats = true,
                    'h' => cli.help = true,
                    'V' => cli.version = true,
                    'c' => {
                        let mut values = Vec::new();
                        if j + 1 < chars.len() {
                            values.push(chars[j + 1..].iter().collect());
                            j = chars.len();
                        }
                        let (mut more, next) = collect_multi_values(args, i + 1);
                        values.append(&mut more);
                        if values.is_empty() {
                            return Err(ParseErrorKind::MissingValue {
                                display: "--create <files>...",
                            });
                        }
                        cli.create = Some(values);
                        i = next;
                        continue;
                    }
                    'o' => {
                        let value = if j + 1 < chars.len() {
                            chars[j + 1..].iter().collect()
                        } else {
                            let value = expect_value(args, i + 1, "--output <output>")?;
                            i += 1;
                            value
                        };
                        cli.output = Some(value);
                        break;
                    }
                    't' => {
                        let value = if j + 1 < chars.len() {
                            chars[j + 1..].iter().collect()
                        } else {
                            let value = expect_value(args, i + 1, "--to <to>")?;
                            i += 1;
                            value
                        };
                        if !is_valid_to(&value) {
                            return Err(ParseErrorKind::InvalidTo(value));
                        }
                        cli.to = Some(value);
                        break;
                    }
                    'L' => {
                        let value = if j + 1 < chars.len() {
                            chars[j + 1..].iter().collect()
                        } else {
                            let value = expect_value(args, i + 1, "--lang <lang>")?;
                            i += 1;
                            value
                        };
                        cli.runtime_lang = Some(value);
                        break;
                    }
                    _ => {
                        return Err(ParseErrorKind::UnexpectedArg {
                            arg: format!("-{ch}"),
                            tip: true,
                        });
                    }
                }
                j += 1;
            }
            i += 1;
            continue;
        }
        push_positional(&mut cli, arg.clone())?;
        i += 1;
    }

    if cli.output.is_some() && cli.to.is_none() {
        return Err(ParseErrorKind::MissingToForOutput);
    }

    Ok(cli)
}

fn push_positional(cli: &mut Cli, value: String) -> Result<(), ParseErrorKind> {
    if cli.book.is_some() {
        return Err(ParseErrorKind::UnexpectedArg {
            arg: value,
            tip: false,
        });
    }
    cli.book = Some(value);
    Ok(())
}

fn collect_multi_values(args: &[String], mut index: usize) -> (Vec<String>, usize) {
    let mut values = Vec::new();
    while index < args.len() {
        let next = &args[index];
        if next.starts_with('-') {
            break;
        }
        values.push(next.clone());
        index += 1;
    }
    (values, index)
}

fn expect_value(args: &[String], index: usize, display: &'static str) -> Result<String, ParseErrorKind> {
    if index >= args.len() || args[index].starts_with('-') {
        return Err(ParseErrorKind::MissingValue { display });
    }
    Ok(args[index].clone())
}

fn is_valid_to(value: &str) -> bool {
    matches!(value, "epub" | "pdf" | "html" | "tex" | "odt" | "html.dir")
}

fn format_parse_error(kind: ParseErrorKind) -> String {
    match kind {
        ParseErrorKind::MissingValue { display } => {
            format!(
                "error: a value is required for '{display}' but none was supplied\n\nFor more information, try '--help'.\n"
            )
        }
        ParseErrorKind::TwoValuesRequired => {
            "error: 2 values required by '--set <set> <set>...'; only 1 was provided\n\nUsage: executable [OPTIONS] [BOOK]\n\nFor more information, try '--help'.\n".to_string()
        }
        ParseErrorKind::UnexpectedArg { arg, tip } => {
            let mut s = format!("error: unexpected argument '{arg}' found\n\n");
            if tip {
                let _ = writeln!(
                    s,
                    "  tip: to pass '{arg}' as a value, use '-- {arg}'\n"
                );
            }
            s.push_str("Usage: executable [OPTIONS] [BOOK]\n\nFor more information, try '--help'.\n");
            s
        }
        ParseErrorKind::MissingToForOutput => {
            "error: the following required arguments were not provided:\n  --to <to>\n\nUsage: executable --to <to> --output <output> <BOOK>\n\nFor more information, try '--help'.\n".to_string()
        }
        ParseErrorKind::InvalidTo(value) => {
            format!(
                "error: invalid value '{value}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n"
            )
        }
    }
}

fn run(mut cli: Cli) -> i32 {
    if cli.help {
        print!("{HELP_TEXT}");
        return 0;
    }
    if cli.version {
        println!("{VERSION}");
        return 0;
    }

    if let Some(files) = cli.create.take() {
        maybe_banner(cli.quiet);
        print_create(files);
        return 0;
    }

    if cli.list_options {
        maybe_banner(cli.quiet);
        print!("{LIST_OPTIONS_TEXT}");
        return 0;
    }

    if let Some(name) = cli.print_template.as_deref() {
        maybe_banner(cli.quiet);
        match template_text(name) {
            Some(text) => print!("{text}"),
            None => eprintln!("ERROR {name} is not a valid template name"),
        }
        return 0;
    }

    let Some(book_arg) = cli.book.as_deref() else {
        maybe_banner(cli.quiet);
        eprintln!("ERROR You must pass the name of a book configuration file.");
        eprintln!("For more information try --help.");
        return 0;
    };

    maybe_banner(cli.quiet);

    let source_path = PathBuf::from(book_arg);
    let load_result = if cli.single {
        load_single_book(&source_path)
    } else {
        load_book_config(&source_path)
    };
    let mut book = match load_result {
        Ok(book) => book,
        Err(message) => {
            eprintln!("ERROR {message}");
            return 0;
        }
    };

    if cli.autograph {
        let _ = writeln!(io::stdout(), "Enter autograph:");
        let _ = io::stdout().flush();
        let mut input = String::new();
        if io::stdin().read_to_string(&mut input).is_ok() {
            let autograph = input.lines().next().unwrap_or_default().trim_end().to_string();
            book.options.insert("autograph".to_string(), autograph);
        }
    }

    if !cli.set_values.is_empty() {
        if cli.set_values.len() % 2 != 0 {
            eprintln!("ERROR An odd number of arguments was passed to --set, but it takes");
            eprintln!("a list of key value pairs.");
            return 0;
        }
        if let Err(message) = apply_set_values(&mut book, &cli.set_values) {
            eprintln!("ERROR {message}");
            return 0;
        }
    }

    if cli.stats {
        print!("{}", render_stats(&book));
        return 0;
    }

    let rendered = render_book(&book);
    if let Some(target) = cli.to.as_deref().and_then(parse_target) {
        render_explicit_target(&cli, &book, &rendered, target);
        return 0;
    }

    let targets = implicit_targets(&book);
    if targets.is_empty() {
        return 0;
    }

    let diagnostics = render_implicit_targets(&cli, &book, &rendered, &targets);
    print_diagnostics(&diagnostics, cli.quiet, true);
    0
}

fn maybe_banner(quiet: bool) {
    if !quiet {
        eprintln!("{BANNER}");
    }
}

fn print_create(files: Vec<String>) {
    print!("{CREATE_TEMPLATE_HEAD}");
    for file in files {
        println!("+ {file}");
    }
}

fn template_text(name: &str) -> Option<&'static str> {
    match name {
        "tex.template" => Some(TEX_TEMPLATE),
        "html.css" => Some(HTML_CSS),
        "html.standalone.template" => Some(HTML_STANDALONE_TEMPLATE),
        "html.dir.template" => Some(HTML_DIR_TEMPLATE),
        "html.js" => Some(HTML_JS),
        "html.css.print" => Some(HTML_PRINT_CSS),
        "epub.css" => Some(EPUB_CSS),
        "epub.chapter.xhtml" => Some(EPUB_CHAPTER_TEMPLATE),
        "epub.titlepage.xhtml" => Some(EPUB_TITLEPAGE_TEMPLATE),
        _ => None,
    }
}

fn load_single_book(path: &Path) -> Result<Book, String> {
    if !path.exists() {
        let name = path.display();
        return Err(format!("{name}: Could not find file '{name}' for book chapter"));
    }
    let content = fs::read_to_string(path)
        .map_err(|_| format!("{}: Could not find file '{}' for book chapter", path.display(), path.display()))?;
    let (options, markdown) = split_front_matter(&content);
    Ok(Book {
        source_path: path.to_path_buf(),
        base_dir: absolute_base_dir(path),
        options,
        chapters: vec![ChapterSource {
            source_name: file_name_string(path),
            content: markdown,
        }],
    })
}

fn load_book_config(path: &Path) -> Result<Book, String> {
    if !path.exists() {
        return Err(format!("Could not find file '{}' for book", path.display()));
    }
    let text = fs::read_to_string(path)
        .map_err(|_| format!("Could not find file '{}' for book", path.display()))?;
    let mut book = Book {
        source_path: path.to_path_buf(),
        base_dir: absolute_base_dir(path),
        options: BTreeMap::new(),
        chapters: Vec::new(),
    };
    let lines: Vec<&str> = text.lines().collect();
    for (index, raw_line) in lines.iter().enumerate() {
        let line_number = index + 1;
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(rest) = line.strip_prefix('+') {
            let rel = rest.trim();
            let chapter_path = book.base_dir.join(rel);
            if !chapter_path.exists() {
                return Err(format!(
                    "{}:{}: Could not find file '{}' for book chapter",
                    path.display(),
                    line_number,
                    rel
                ));
            }
            let content = fs::read_to_string(&chapter_path).map_err(|_| {
                format!(
                    "{}:{}: Could not find file '{}' for book chapter",
                    path.display(),
                    line_number,
                    rel
                )
            })?;
            book.chapters.push(ChapterSource {
                source_name: rel.to_string(),
                content,
            });
            continue;
        }
        if let Some((key, value)) = split_option_line(line) {
            if !is_known_option(key) {
                return Err(format!(
                    "{}:{}: Error converting BookOption: unrecognized key '{}'",
                    path.display(),
                    line_number,
                    key
                ));
            }
            book.options.insert(key.to_string(), value.to_string());
        }
    }
    Ok(book)
}

fn split_front_matter(content: &str) -> (BTreeMap<String, String>, String) {
    let mut options = BTreeMap::new();
    if !content.starts_with("---\n") {
        return (options, content.to_string());
    }
    let remainder = &content[4..];
    if let Some(end) = remainder.find("\n---") {
        let block = &remainder[..end];
        for line in block.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            if let Some((key, value)) = split_option_line(trimmed) {
                options.insert(key.to_string(), value.to_string());
            }
        }
        let after = &remainder[end + 4..];
        let markdown = after.strip_prefix('\n').unwrap_or(after).to_string();
        (options, markdown)
    } else {
        (options, content.to_string())
    }
}

fn split_option_line(line: &str) -> Option<(&str, &str)> {
    let (key, value) = line.split_once(':')?;
    Some((key.trim(), value.trim()))
}

fn absolute_base_dir(path: &Path) -> PathBuf {
    path.parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."))
}

fn file_name_string(path: &Path) -> String {
    path.file_name()
        .and_then(|s| s.to_str())
        .unwrap_or_default()
        .to_string()
}

fn known_option_keys() -> BTreeSet<String> {
    let mut keys = BTreeSet::new();
    for line in LIST_OPTIONS_TEXT.lines() {
        if line.is_empty() || line.starts_with(' ') {
            continue;
        }
        if line.chars().all(|c| c.is_ascii_uppercase() || c == ' ' || c == '[' || c == ']' || c == '#' || c == '(' || c == ')' || c == ':' || c == '_') {
            continue;
        }
        if line.contains(' ') {
            continue;
        }
        keys.insert(line.to_string());
    }
    keys.insert("output.odt".to_string());
    keys
}

fn is_known_option(key: &str) -> bool {
    known_option_keys().contains(key)
}

fn apply_set_values(book: &mut Book, values: &[String]) -> Result<(), String> {
    let known = known_option_keys();
    let book_name = book
        .source_path
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("book.book");
    for pair in values.chunks_exact(2) {
        let key = &pair[0];
        let value = &pair[1];
        if !known.contains(key) {
            return Err(format!(
                "Error in setting key {key}: {book_name}:3: Error converting BookOption: unrecognized key '{key}'"
            ));
        }
        book.options.insert(key.clone(), value.clone());
    }
    Ok(())
}

fn parse_target(value: &str) -> Option<Target> {
    match value {
        "html" => Some(Target::Html),
        "epub" => Some(Target::Epub),
        "pdf" => Some(Target::Pdf),
        "tex" => Some(Target::Tex),
        "odt" => Some(Target::Odt),
        "html.dir" => Some(Target::HtmlDir),
        _ => None,
    }
}

fn implicit_targets(book: &Book) -> Vec<(Target, OutputPath)> {
    let mut targets = Vec::new();
    if let Some(path) = book.options.get("output.html") {
        targets.push((Target::Html, OutputPath::File(resolve_book_output_path(book, path))));
    }
    if let Some(path) = book.options.get("output.epub") {
        targets.push((Target::Epub, OutputPath::File(resolve_book_output_path(book, path))));
    }
    if let Some(path) = book.options.get("output.tex") {
        targets.push((Target::Tex, OutputPath::File(resolve_book_output_path(book, path))));
    }
    if let Some(path) = book.options.get("output.pdf") {
        targets.push((Target::Pdf, OutputPath::File(resolve_book_output_path(book, path))));
    }
    if let Some(path) = book.options.get("output.html.dir") {
        targets.push((Target::HtmlDir, OutputPath::Dir(resolve_book_output_path(book, path))));
    }
    if let Some(list) = book.options.get("output") {
        for name in parse_output_list(list) {
            match parse_target(&name) {
                Some(Target::Html) if !contains_target(&targets, Target::Html) => {
                    targets.push((
                        Target::Html,
                        OutputPath::File(default_book_output_file(book, "html")),
                    ));
                }
                Some(Target::Epub) if !contains_target(&targets, Target::Epub) => {
                    targets.push((
                        Target::Epub,
                        OutputPath::File(default_book_output_file(book, "epub")),
                    ));
                }
                Some(Target::Tex) if !contains_target(&targets, Target::Tex) => {
                    targets.push((
                        Target::Tex,
                        OutputPath::File(default_book_output_file(book, "tex")),
                    ));
                }
                Some(Target::Pdf) if !contains_target(&targets, Target::Pdf) => {
                    targets.push((
                        Target::Pdf,
                        OutputPath::File(default_book_output_file(book, "pdf")),
                    ));
                }
                Some(Target::HtmlDir) if !contains_target(&targets, Target::HtmlDir) => {
                    targets.push((
                        Target::HtmlDir,
                        OutputPath::Dir(book.base_dir.join("auto")),
                    ));
                }
                _ => {}
            }
        }
    }
    targets
}

fn contains_target(targets: &[(Target, OutputPath)], needle: Target) -> bool {
    targets.iter().any(|(target, _)| *target == needle)
}

fn parse_output_list(value: &str) -> Vec<String> {
    let trimmed = value.trim();
    let inner = trimmed
        .strip_prefix('[')
        .and_then(|s| s.strip_suffix(']'))
        .unwrap_or(trimmed);
    inner
        .split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn default_book_output_file(book: &Book, extension: &str) -> PathBuf {
    let stem = book
        .source_path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("book");
    resolve_book_output_path(book, &format!("{stem}.{extension}"))
}

fn resolve_book_output_path(book: &Book, path: &str) -> PathBuf {
    let mut out = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        book.base_dir.join(path)
    };
    if let Some(base) = book.options.get("output.base_path") {
        if !base.is_empty() && !Path::new(path).is_absolute() {
            out = book.base_dir.join(base).join(path);
        }
    }
    out
}

fn render_explicit_target(cli: &Cli, book: &Book, rendered: &RenderedBook, target: Target) {
    let output = match target {
        Target::HtmlDir => cli
            .output
            .as_ref()
            .map(|p| OutputPath::Dir(PathBuf::from(p)))
            .or_else(|| {
                book.options
                    .get("output.html.dir")
                    .map(|p| OutputPath::Dir(resolve_book_output_path(book, p)))
            })
            .unwrap_or(OutputPath::Stream),
        _ => cli
            .output
            .as_ref()
            .map(|p| OutputPath::File(PathBuf::from(p)))
            .or_else(|| {
                match target {
                    Target::Html => book
                        .options
                        .get("output.html")
                        .map(|p| OutputPath::File(resolve_book_output_path(book, p))),
                    Target::Epub => book
                        .options
                        .get("output.epub")
                        .map(|p| OutputPath::File(resolve_book_output_path(book, p))),
                    Target::Tex => book
                        .options
                        .get("output.tex")
                        .map(|p| OutputPath::File(resolve_book_output_path(book, p))),
                    Target::Pdf => book
                        .options
                        .get("output.pdf")
                        .map(|p| OutputPath::File(resolve_book_output_path(book, p))),
                    Target::Odt | Target::HtmlDir => None,
                }
            })
            .unwrap_or(OutputPath::Stream),
    };

    match target {
        Target::Html => {
            let html = render_html_document(book, rendered);
            let _ = write_string_output(&output, &html);
        }
        Target::Tex => {
            let tex = render_tex_document(book);
            let _ = write_string_output(&output, &tex);
        }
        Target::Epub => match render_epub_bytes(book, rendered) {
            Ok((bytes, diagnostics)) => {
                let _ = write_binary_output(&output, &bytes);
                print_diagnostics(&diagnostics, cli.quiet, false);
            }
            Err(diagnostics) => print_diagnostics(&diagnostics, cli.quiet, false),
        },
        Target::Pdf => match render_pdf(book, &output) {
            Ok(diagnostics) => print_diagnostics(&diagnostics, cli.quiet, false),
            Err(message) => eprintln!("ERROR {message}"),
        },
        Target::Odt => eprintln!("ERROR unknown format odt"),
        Target::HtmlDir => {
            if output == OutputPath::Stream {
                eprintln!("ERROR Error during rendering: can only render HTML directory to a path, not to a stream");
            } else {
                let diagnostics = render_html_dir(book, rendered, &output);
                print_diagnostics(&diagnostics, cli.quiet, false);
            }
        }
    }
}

fn render_implicit_targets(
    cli: &Cli,
    book: &Book,
    rendered: &RenderedBook,
    targets: &[(Target, OutputPath)],
) -> Vec<Diagnostic> {
    let mut diagnostics = Vec::new();
    for (target, output) in targets {
        match target {
            Target::Html => {
                let html = render_html_document(book, rendered);
                let _ = write_string_output(output, &html);
            }
            Target::Tex => {
                let tex = render_tex_document(book);
                let _ = write_string_output(output, &tex);
            }
            Target::Epub => match render_epub_bytes(book, rendered) {
                Ok((bytes, mut diags)) => {
                    let _ = write_binary_output(output, &bytes);
                    diagnostics.append(&mut diags);
                }
                Err(mut diags) => diagnostics.append(&mut diags),
            },
            Target::Pdf => match render_pdf(book, output) {
                Ok(mut diags) => diagnostics.append(&mut diags),
                Err(message) => diagnostics.push(Diagnostic {
                    level: Level::Error,
                    text: format!("Error rendering pdf: {message}"),
                    detailed: None,
                }),
            },
            Target::HtmlDir => {
                let mut diags = render_html_dir(book, rendered, output);
                if cli.quiet {
                    for diag in &mut diags {
                        if diag.level == Level::Error && diag.detailed.is_none() {
                            diag.detailed = Some(HTML_DIR_TEMPLATE_ERROR.to_string());
                        }
                    }
                }
                diagnostics.extend(diags.into_iter().map(|mut diag| {
                    diag.text = format!("Error rendering html.dir: {}", diag.text);
                    diag
                }));
            }
            Target::Odt => {}
        }
    }
    diagnostics
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum OutputPath {
    Stream,
    File(PathBuf),
    Dir(PathBuf),
}

fn write_string_output(output: &OutputPath, text: &str) -> io::Result<()> {
    match output {
        OutputPath::Stream => {
            print!("{text}");
            Ok(())
        }
        OutputPath::File(path) => {
            ensure_parent(path)?;
            fs::write(path, text)
        }
        OutputPath::Dir(_) => Ok(()),
    }
}

fn write_binary_output(output: &OutputPath, bytes: &[u8]) -> io::Result<()> {
    match output {
        OutputPath::Stream => {
            io::stdout().write_all(bytes)?;
            Ok(())
        }
        OutputPath::File(path) => {
            ensure_parent(path)?;
            fs::write(path, bytes)
        }
        OutputPath::Dir(_) => Ok(()),
    }
}

fn ensure_parent(path: &Path) -> io::Result<()> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent)?;
        }
    }
    Ok(())
}

fn render_book(book: &Book) -> RenderedBook {
    let mut state = RenderState {
        next_link_id: 1,
        next_para_id: 1,
        next_chapter_number: 1,
    };
    let mut rendered = RenderedBook::default();
    for chapter in &book.chapters {
        let raw_html = render_markdown_html(&chapter.content);
        let transformed = transform_chapter_html(&raw_html, &mut state);
        let body_html = format!(
            "<div id = \"chapter-{}\" class = \"chapter\">\n{}\n</div>",
            rendered.files.len(),
            transformed
        );
        let title = first_visible_title(&raw_html);
        if !transformed.toc_entries.is_empty() {
            rendered.toc_entries.extend(transformed.toc_entries);
        }
        rendered.files.push(HtmlChapterFile {
            source_name: chapter.source_name.clone(),
            title,
            body_html,
        });
    }
    rendered
}

struct TransformedChapter {
    html: String,
    toc_entries: Vec<TocEntry>,
}

fn transform_chapter_html(raw_html: &str, state: &mut RenderState) -> TransformedChapter {
    let mut out = String::new();
    let mut toc_entries = Vec::new();
    let mut cursor = 0usize;
    let mut found_h1 = false;
    while cursor < raw_html.len() {
        if let Some(rest) = raw_html[cursor..].strip_prefix("<h1>") {
            if let Some(end_rel) = rest.find("</h1>") {
                found_h1 = true;
                let inner = &rest[..end_rel];
                let link_id = state.next_link_id;
                let chapter_number = state.next_chapter_number;
                state.next_link_id += 1;
                state.next_chapter_number += 1;
                let plain = plain_text_from_html(inner);
                toc_entries.push(TocEntry {
                    link_id,
                    label: if plain.is_empty() {
                        format!("{chapter_number}.")
                    } else {
                        format!("{chapter_number}. {plain}")
                    },
                });
                out.push_str(&special_chapter_heading(chapter_number, link_id, inner));
                cursor += 4 + end_rel + 5;
                continue;
            }
        }
        for level in 2..=6 {
            let open = format!("<h{level}>");
            let close = format!("</h{level}>");
            if let Some(rest) = raw_html[cursor..].strip_prefix(&open) {
                if let Some(end_rel) = rest.find(&close) {
                    let inner = &rest[..end_rel];
                    let link_id = state.next_link_id;
                    state.next_link_id += 1;
                    let _ = write!(
                        out,
                        "<h{level} id = \"link-{link_id}\">{inner}</h{level}>"
                    );
                    cursor += open.len() + end_rel + close.len();
                    break;
                }
            }
        }
        if raw_html[cursor..].starts_with("<p>") {
            if let Some(end_rel) = raw_html[cursor + 3..].find("</p>") {
                let inner = &raw_html[cursor + 3..cursor + 3 + end_rel];
                let para_id = state.next_para_id;
                state.next_para_id += 1;
                let _ = write!(out, "<p id = \"para-{para_id}\">{inner}</p>");
                cursor += 3 + end_rel + 4;
                continue;
            }
        }
        let ch = raw_html[cursor..].chars().next().unwrap_or_default();
        out.push(ch);
        cursor += ch.len_utf8();
    }
    if !found_h1 {
        let chapter_number = state.next_chapter_number;
        let link_id = state.next_link_id;
        state.next_link_id += 1;
        state.next_chapter_number += 1;
        out = format!(
            "{}{}",
            special_chapter_heading(chapter_number, link_id, ""),
            out
        );
        toc_entries.push(TocEntry {
            link_id,
            label: format!("{chapter_number}."),
        });
    }
    TransformedChapter { html: out, toc_entries }
}

fn special_chapter_heading(number: usize, link_id: usize, inner: &str) -> String {
    if inner.is_empty() {
        format!(
            "  <h1 id = 'link-{link_id}'><span class = 'chapter-header'>Chapter {number}</span></h1>"
        )
    } else {
        format!(
            "  <h1 id = 'link-{link_id}'><span class = 'chapter-header'>Chapter {number}</span><br />{inner}</h1>"
        )
    }
}

fn first_visible_title(raw_html: &str) -> String {
    if let Some(start) = raw_html.find("<h1>") {
        let rest = &raw_html[start + 4..];
        if let Some(end) = rest.find("</h1>") {
            return plain_text_from_html(&rest[..end]);
        }
    }
    String::new()
}

fn render_markdown_html(markdown: &str) -> String {
    let mut options = Options::empty();
    options.insert(Options::ENABLE_TABLES);
    options.insert(Options::ENABLE_FOOTNOTES);
    options.insert(Options::ENABLE_STRIKETHROUGH);
    options.insert(Options::ENABLE_TASKLISTS);
    let parser = Parser::new_ext(markdown, options);
    let mut html_out = String::new();
    html::push_html(&mut html_out, parser);
    html_out
}

fn render_html_document(book: &Book, rendered: &RenderedBook) -> String {
    let title = escape_html(book_title(book));
    let author = escape_html(book_author(book));
    let subtitle = book.options.get("subtitle").cloned().unwrap_or_default();
    let lang = escape_html(book_lang(book));
    let autograph = book.options.get("autograph").cloned().unwrap_or_default();
    let has_toc = rendered.toc_entries.len() > 1;
    let mut out = String::new();
    let _ = write!(
        out,
        "<!DOCTYPE html>\n<html lang=\"{lang}\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"generator\" content=\"crowbook\">\n    <meta name=\"viewport\" content=\"width=device-width\">\n    <meta name=\"author\" content=\"{author}\">\n    \n    <title>{title}</title>\n    <style type = \"text/css\">\n      {HTML_CSS}\n    </style>\n    <style type = \"text/css\" media = \"print\">\n      {HTML_PRINT_CSS}\n    </style>\n   <script>\n{HTML_JS}\n   </script>\n\n\n  </head>\n  <body>\n    {}\n",
        json_ld(book)
    );
    if has_toc {
        let _ = write!(
            out,
            "    <nav id = \"nav\">\n      \n      <div id = \"nav-title\">\n        <h2><a href = \"#link-0\">{title}</a></h2>\n      </div>\n          <ul>\n"
        );
        for entry in &rendered.toc_entries {
            let _ = writeln!(
                out,
                "      <li><a href=\"#link-{}\">{}</a></li>",
                entry.link_id,
                escape_html(&entry.label)
            );
        }
        out.push_str("    </ul>\n    </nav>\n\n");
    }
    out.push_str("    <div id = \"content\">\n      \n      <div id = \"page\">\n        <header>\n\n          <div id = \"menu\">\n");
    if has_toc {
        let menu_svg = include_str!("../observed/menu_svg.txt").trim();
        let _ = write!(
            out,
            "\t        \n            <img id = \"menu-button\" onclick=\"toggle();\"\n                 src=\"{menu_svg}\"\n                 alt = \"Table of contents\" title = \"Table of contents\" />\n          \n"
        );
    } else {
        out.push_str("\t        \n");
    }
    let _ = write!(
        out,
        "          </div>\n\t  <h2 class=\"author\">{author}</h2>\n          <h1 id = \"link-0\" class=\"title\" >{title}</h1>\n"
    );
    if !subtitle.is_empty() {
        let _ = writeln!(
            out,
            "\t  <h2 class = \"subtitle\">{}</h2>",
            escape_html(&subtitle)
        );
    } else {
        out.push_str("\t  \n");
    }
    if !autograph.is_empty() {
        let _ = write!(
            out,
            "\t  \n\t  <div id = \"autograph\">\n\t    {}\n\t  </div>\n",
            escape_html(&autograph)
        );
    } else {
        out.push_str("\t  \n");
    }
    out.push_str("\t  \n        </header>\n\n");
    for file in &rendered.files {
        out.push_str(&file.body_html);
        out.push('\n');
    }
    out.push_str("\n      </div>\n      \n    </div>\n  </body>\n</html>\n");
    out
}

fn json_ld(book: &Book) -> String {
    format!(
        "<script type = 'application/ld+json'>\n{{\n    \"@context\": \"http://schema.org/\",\n    \"@type\": \"Book\",\n    \"author\": \"{}\",\n    \"name\": \"{}\",\n    \n    \n    \n    \n    \n    \"inLanguage\": \"{}\"\n}}\n</script>",
        escape_json(book_author(book)),
        escape_json(book_title(book)),
        escape_json(book_lang(book))
    )
}

fn render_html_dir(book: &Book, rendered: &RenderedBook, output: &OutputPath) -> Vec<Diagnostic> {
    let OutputPath::Dir(dir) = output else {
        return vec![Diagnostic {
            level: Level::Error,
            text: HTML_DIR_TEMPLATE_ERROR.to_string(),
            detailed: None,
        }];
    };
    let _ = fs::create_dir_all(dir);
    let _ = fs::write(dir.join("stylesheet.css"), HTML_CSS);
    let _ = fs::write(dir.join("print.css"), HTML_PRINT_CSS);
    for (index, file) in rendered.files.iter().enumerate() {
        let page = render_html_dir_page(book, rendered, file, index);
        let _ = fs::write(dir.join(format!("chapter_{index:03}.html")), page);
    }
    vec![Diagnostic {
        level: Level::Error,
        text: HTML_DIR_TEMPLATE_ERROR.to_string(),
        detailed: None,
    }]
}

fn render_html_dir_page(
    book: &Book,
    rendered: &RenderedBook,
    file: &HtmlChapterFile,
    index: usize,
) -> String {
    let title = escape_html(book_title(book));
    let chapter_title = if file.title.is_empty() {
        format!("{}", index + 1)
    } else {
        format!("{}. {}", index + 1, file.title)
    };
    format!(
        "<!DOCTYPE html>\n<html lang=\"{}\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"generator\" content=\"crowbook\">\n    <meta name=\"author\" content=\"{}\">\n    <meta name=\"viewport\" content=\"width=device-width\">\n    \n    <title>{} - {}</title>\n    <link rel = \"stylesheet\" href = \"stylesheet.css\" type = \"text/css\"\n          />\n    <link rel = \"stylesheet\" href = \"print.css\" type = \"text/css\"\n          media = \"print\" />\n    \n   <script>\n{}\n   </script>\n\n\n  </head>  \n  <body>\n  {}\n  <nav id = \"nav\">\n    <h2><a href = \"index.html\">{}</a></h2>\n        <ul>\n{}\n    </ul>\n  </nav>\n  <div id = \"content\">\n    <div id = \"page\">\n{}\n    </div>\n  </div>\n  </body>\n</html>\n",
        escape_html(book_lang(book)),
        escape_html(book_author(book)),
        title,
        escape_html(&chapter_title),
        HTML_JS,
        json_ld(book),
        title,
        rendered
            .toc_entries
            .iter()
            .map(|entry| format!(
                "      <li><a href=\"chapter_{:03}.html\">{}</a></li>\n",
                index,
                escape_html(&entry.label)
            ))
            .collect::<String>(),
        file.body_html
    )
}

fn render_tex_document(book: &Book) -> String {
    let lang = tex_lang(book_lang(book));
    let title = escape_tex(book_title(book));
    let author = escape_tex(book_author(book));
    let mut body = String::new();
    for chapter in &book.chapters {
        let raw_html = render_markdown_html(&chapter.content);
        let plain = plain_text_from_html(&raw_html);
        let first_title = first_visible_title(&raw_html);
        let content = if let Some(pos) = plain.find(&first_title) {
            plain[pos + first_title.len()..].trim().to_string()
        } else {
            plain.trim().to_string()
        };
        if !first_title.is_empty() {
            let _ = writeln!(body, "\\chapter{{{}}}", escape_tex(&first_title));
            let _ = writeln!(body, "\\label{{chapter-{}}}", body.matches("\\chapter{").count() - 1);
        }
        if !content.is_empty() {
            let _ = writeln!(body, "{}", escape_tex(&content));
            let _ = writeln!(body);
        }
    }
    format!(
        "\\documentclass{{book}}\n\n%% Package inclusion\n\n% Unicode support if xelatex is used\n\\usepackage{{fontspec}}\n\\usepackage{{xunicode}}\n\n\n\\usepackage[{lang}]{{babel}} % Language support\n\\usepackage{{fancyhdr}} % Headers\n\\usepackage{{enumitem}}\n\n% Allows hyphenatations in \\texttt\n\\usepackage[htt]{{hyphenat}}\n\n\n\n% Set hyperlinks and metadata\n\\usepackage[colorlinks=true,breaklinks=true,hypertexnames=false]{{hyperref}}\n\\hypersetup{{pdfauthor={{{author}}},\n  pdftitle={{{title}}},\n  pdfsubject={{}}\n}}\n\n\n\n\n\n\n% Included if the stdpage option if set to false\n\\usepackage[a5paper, top=2cm, bottom=1.5cm,\n  left=2.5cm,right=1.5cm]{{geometry}} % Set dimensions/margins of the page\n\n\n\n\n\n\\makeatletter\n\\date{{}}\n\n\n  \n% Redefine the \\maketitle command, only for book class (not used if stdpage option is set to true)\n\\renewcommand{{\\maketitle}}{{\n  \n\n  % First page with only the title\n  \\thispagestyle{{empty}}\n  \\vspace*{{\\stretch{{1}}}}\n\n  \\begin{{center}}\n    {{\\Huge \\@title   \\\\[5mm]}}\n  \\end{{center}}\n  \\vspace*{{\\stretch{{2}}}}\n\n  \\newpage\n  % Empty left page\n  \\thispagestyle{{empty}}\n  \\cleardoublepage\n\n  % Main title page, with author, title, subtitle, date\n  \\begin{{center}}\n    \\thispagestyle{{empty}}\n    \\vspace*{{\\baselineskip}}\n    \\rule{{\\textwidth}}{{1.6pt}}\\vspace*{{-\\baselineskip}}\\vspace*{{2pt}}\n    \\rule{{\\textwidth}}{{0.4pt}}\\\\[\\baselineskip]\n\n    {{\\Huge\\scshape \\@title   \\\\[5mm]}}\n    {{\\Large }}\n\n    \\rule{{\\textwidth}}{{0.4pt}}\\vspace*{{-\\baselineskip}}\\vspace{{3.2pt}}\n    \\rule{{\\textwidth}}{{1.6pt}}\\\\[\\baselineskip]\n\n    \\vspace*{{4\\baselineskip}}\n\n    {{\\Large \\@author}}\n      \n    \\vfill\n      \n  \\end{{center}}\n\n  \\pagebreak\n  \\newpage\n  % Copyright page with author, version, and license\n  \\thispagestyle{{empty}}\n  \\null\\vfill\n  \\noindent\n  \\begin{{center}}\n    {{\\emph{{\\@title}}.\\\\[5mm]}}\n    \n  \\end{{center}}\n  \\pagebreak\n  \\newpage\n}}\n  \n\n\n% Redefine headers\n\\pagestyle{{fancy}}\n\\fancyhead{{}}\n\\fancyhead[CO,CE]{{\\thepage}}\n\\fancyfoot{{}}\n\n\n\n\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\n% Command and environment definitions\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\n\n% Strong\n\\newcommand\\mdstrong[1]{{\\textbf{{#1}}}}\n\n% Code\n\\newcommand\\mdcode[1]{{\\texttt{{#1}}}}\n\n% Rule\n\\newcommand\\mdrule{{\n  \\nopagebreak\n  {{\\vskip 1em}}\n  \\nopagebreak\n  \\begin{{center}}\n    ***\n  \\end{{center}}\n  \\nopagebreak\n {{\\vskip 1em}}\n \\nopagebreak\n}}\n\n% Hardbreak\n\\newcommand\\mdhardbreak{{\\\\}}\n\n% Block quote$\n\\newenvironment{{mdblockquote}}{{%\n  \\begin{{quotation}}\n    \\itshape\n}}{{%\n  \\end{{quotation}}\n}}\n\n\n% Code block\n\\makeatother\n\n\\title{{{title}}}\n\\author{{{author}}}\n\n\\begin{{document}}\n\n% Redefine chapter and part names if they needs to be\n% Needs to be after \\begin{{document}} because babel\n\n\n\n\n\n\\maketitle\n\n\n\n\n{body}\n\n\\end{{document}}\n"
    )
}

fn render_epub_bytes(book: &Book, rendered: &RenderedBook) -> Result<(Vec<u8>, Vec<Diagnostic>), Vec<Diagnostic>> {
    let mut diagnostics = Vec::new();
    if Command::new("zip").arg("-h").output().is_err() {
        diagnostics.push(Diagnostic {
            level: Level::Warning,
            text: EPUB_WARNING.to_string(),
            detailed: None,
        });
    }
    let version = book
        .options
        .get("epub.version")
        .and_then(|v| v.parse::<u32>().ok())
        .unwrap_or(2);

    let mut bytes = Vec::new();
    let cursor = std::io::Cursor::new(&mut bytes);
    let mut zip = zip::ZipWriter::new(cursor);
    let stored = FileOptions::default().compression_method(CompressionMethod::Stored);
    let deflated = FileOptions::default().compression_method(CompressionMethod::Deflated);

    zip.start_file("mimetype", stored).ok();
    zip.write_all(b"application/epub+zip").ok();

    zip.start_file("META-INF/container.xml", deflated).ok();
    zip.write_all(container_xml().as_bytes()).ok();
    zip.start_file("META-INF/com.apple.ibooks.display-options.xml", deflated)
        .ok();
    zip.write_all(ibooks_display_options().as_bytes()).ok();

    zip.start_file("OEBPS/title_page.xhtml", deflated).ok();
    zip.write_all(epub_title_page(book, version).as_bytes()).ok();

    for (index, file) in rendered.files.iter().enumerate() {
        zip.start_file(format!("OEBPS/chapter_{index:03}.xhtml"), deflated)
            .ok();
        zip.write_all(epub_chapter_page(book, file, index, version).as_bytes())
            .ok();
    }

    zip.start_file("OEBPS/stylesheet.css", deflated).ok();
    zip.write_all(EPUB_CSS.as_bytes()).ok();
    zip.start_file("OEBPS/content.opf", deflated).ok();
    zip.write_all(epub_content_opf(book, rendered, version).as_bytes()).ok();
    zip.start_file("OEBPS/toc.ncx", deflated).ok();
    zip.write_all(epub_toc_ncx(rendered).as_bytes()).ok();
    zip.start_file("OEBPS/nav.xhtml", deflated).ok();
    zip.write_all(epub_nav(book, rendered, version).as_bytes()).ok();
    let _ = zip.finish();

    Ok((bytes, diagnostics))
}

fn container_xml() -> &'static str {
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<container version=\"1.0\" xmlns=\"urn:oasis:names:tc:opendocument:xmlns:container\">\n  <rootfiles>\n    <rootfile full-path=\"OEBPS/content.opf\" media-type=\"application/oebps-package+xml\" />\n  </rootfiles>\n</container>\n"
}

fn ibooks_display_options() -> &'static str {
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<display_options>\n  <platform name=\"*\">\n    <option name=\"specified-fonts\">true</option>\n  </platform>\n</display_options>\n"
}

fn epub_title_page(book: &Book, version: u32) -> String {
    let title = escape_html(book_title(book));
    let author = escape_html(book_author(book));
    let lang = escape_html(book_lang(book));
    if version >= 3 {
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html>\n<html xmlns=\"http://www.w3.org/1999/xhtml\"\n      xmlns:epub=\"http://www.idpf.org/2007/ops\" xml:lang=\"{lang}\" lang=\"{lang}\">\n<head>\n  <meta charset = \"utf-8\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{title}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n  <section epub:type = \"titlepage\">\n    <h2 class=\"author\">{author}</h2>\n    <h1 class=\"title\">{title}</h1>\n    \n    \n  </section>\n</body>\n</html>\n"
        )
    } else {
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"{lang}\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{title}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n  <h2 class=\"author\">{author}</h2>\n  <h1 class=\"title\">{title}</h1>\n  \n  \n</body>\n</html>\n"
        )
    }
}

fn epub_chapter_page(book: &Book, file: &HtmlChapterFile, index: usize, version: u32) -> String {
    let lang = escape_html(book_lang(book));
    let title = if file.title.is_empty() {
        format!("{}", index + 1)
    } else {
        format!("{}. {}", index + 1, file.title)
    };
    let body = strip_chapter_wrapper(&file.body_html);
    if version >= 3 {
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html>\n<html xmlns=\"http://www.w3.org/1999/xhtml\"\n      xmlns:epub=\"http://www.idpf.org/2007/ops\" xml:lang = \"{lang}\" lang=\"{lang}\">\n  <head>\n    <meta charset = \"utf-8\" />\n    <meta name=\"generator\" content=\"crowbook\" />\n    <title>{}</title>\n    <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n  </head>\n  <body xml:lang=\"{lang}\" lang=\"{lang}\">\n    <section class = \"level1\">\n      {}\n\n    </section>\n  </body>\n</html>\n",
            escape_html(&title),
            body
        )
    } else {
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"{lang}\" lang=\"{lang}\">\n  <head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>{}</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n  </head>\n  <body xml:lang=\"{lang}\" lang=\"{lang}\">\n    <div id = \"page\">\n      {}\n\n    </div>\n  </body>\n</html>\n",
            escape_html(&title),
            body
        )
    }
}

fn strip_chapter_wrapper(html: &str) -> &str {
    if let Some(start) = html.find(">\n") {
        if let Some(end) = html.rfind("\n</div>") {
            return &html[start + 2..end];
        }
    }
    html
}

fn epub_content_opf(book: &Book, rendered: &RenderedBook, version: u32) -> String {
    let title = escape_xml(book_title(book));
    let lang = escape_xml(book_lang(book));
    let timestamp = iso_timestamp();
    let mut manifest = String::new();
    let mut spine = String::new();
    let mut guide = String::new();
    manifest.push_str("    <item id=\"ncx\" href=\"toc.ncx\" media-type=\"application/x-dtbncx+xml\"/>\n");
    if version >= 3 {
        manifest.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\" properties=\"nav\"/>\n");
    } else {
        manifest.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\"/>\n");
    }
    manifest.push_str("    <item media-type=\"application/xhtml+xml\" id=\"id_title_page.xhtml\" href=\"title_page.xhtml\"/>\n");
    spine.push_str("    <itemref idref=\"id_title_page.xhtml\"/>\n");
    guide.push_str("    <reference type=\"toc\" title=\"Table of contents\" href=\"nav.xhtml\"/>\n");
    guide.push_str("    <reference type=\"title-page\" title=\"Title\" href=\"title_page.xhtml\"/>\n");
    for (index, file) in rendered.files.iter().enumerate() {
        manifest.push_str(&format!(
            "    <item media-type=\"application/xhtml+xml\" id=\"id_chapter_{index:03}.xhtml\" href=\"chapter_{index:03}.xhtml\"/>\n"
        ));
        spine.push_str(&format!(
            "    <itemref idref=\"id_chapter_{index:03}.xhtml\"/>\n"
        ));
        let title_label = if file.title.is_empty() {
            format!("{}", index + 1)
        } else {
            format!("{}. {}", index + 1, file.title)
        };
        guide.push_str(&format!(
            "    <reference type=\"text\" title=\"{}\" href=\"chapter_{index:03}.xhtml\"/>\n",
            escape_xml(&title_label)
        ));
    }
    manifest.push_str("    <item media-type=\"text/css\" id=\"id_stylesheet.css\" href=\"stylesheet.css\"/>\n");
    if version >= 3 {
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<package version=\"3.0\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n  <metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"\n            xmlns:opf=\"http://www.idpf.org/2007/opf\">\n    <dc:identifier id=\"epub-id-1\">urn:uuid:00000000-0000-0000-0000-000000000000</dc:identifier>\n    <dc:title>{title}</dc:title>\n    \n    \n    <dc:language id=\"epub-creator-0\">{lang}</dc:language>\n    \n    \n    <meta property=\"dcterms:modified\">{timestamp}</meta>\n\n  </metadata>\n  <manifest>\n{manifest}  </manifest>\n  <spine toc=\"ncx\" page-progression-direction=\"ltr\">\n{spine}  </spine>\n  <guide>\n{guide}  </guide>\n</package>\n"
        )
    } else {
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<package version=\"2.0\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n  <metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"\n            xmlns:opf=\"http://www.idpf.org/2007/opf\">\n    <dc:identifier id=\"epub-id-1\">urn:uuid:00000000-0000-0000-0000-000000000000</dc:identifier>\n    <dc:title>{title}</dc:title>\n    \n    \n    <dc:language>{lang}</dc:language>\n    \n    \n\n  </metadata>\n  <manifest>\n{manifest}  </manifest>\n  <spine toc=\"ncx\">\n{spine}  </spine>\n  <guide>\n{guide}  </guide>\n</package>\n"
        )
    }
}

fn epub_toc_ncx(rendered: &RenderedBook) -> String {
    let mut nav_points = String::new();
    nav_points.push_str("    <navPoint playOrder=\"1\" id=\"navPoint-1\">\n      <navLabel>\n       <text>Title</text>\n      </navLabel>\n      <content src=\"title_page.xhtml\"/>\n    </navPoint>\n");
    for (index, file) in rendered.files.iter().enumerate() {
        let label = if file.title.is_empty() {
            format!("{}", index + 1)
        } else {
            format!("{}. {}", index + 1, file.title)
        };
        nav_points.push_str(&format!(
            "    <navPoint playOrder=\"{}\" id=\"navPoint-{}\">\n      <navLabel>\n       <text>{}</text>\n      </navLabel>\n      <content src=\"chapter_{index:03}.xhtml\"/>\n    </navPoint>\n",
            index + 2,
            index + 2,
            escape_xml(&label)
        ));
    }
    format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ncx version=\"2005-1\" xmlns=\"http://www.daisy.org/z3986/2005/ncx/\">\n  <head>\n    <meta name=\"dtb:depth\" content=\"1\" />\n    <meta name=\"dtb:totalPageCount\" content=\"0\" />\n    <meta name=\"dtb:maxPageNumber\" content=\"0\" />\n  </head>\n  <docTitle>\n    <text>Table of contents</text>\n  </docTitle>\n  <navMap>\n{nav_points}  </navMap>\n</ncx>\n"
    )
}

fn epub_nav(book: &Book, rendered: &RenderedBook, version: u32) -> String {
    let mut items = String::new();
    items.push_str("      <li><a href=\"title_page.xhtml\">Title</a></li>\n");
    for (index, file) in rendered.files.iter().enumerate() {
        let label = if file.title.is_empty() {
            format!("{}", index + 1)
        } else {
            format!("{}. {}", index + 1, file.title)
        };
        items.push_str(&format!(
            "      <li><a href=\"chapter_{index:03}.xhtml\">{}</a></li>\n",
            escape_html(&label)
        ));
    }
    if version >= 3 {
        let mut landmarks = String::new();
        landmarks.push_str("      <li><a epub:type=\"titlepage\" href=\"title_page.xhtml\">Title</a></li>\n");
        for (index, file) in rendered.files.iter().enumerate() {
            let label = if file.title.is_empty() {
                format!("{}", index + 1)
            } else {
                format!("{}. {}", index + 1, file.title)
            };
            landmarks.push_str(&format!(
                "      <li><a epub:type=\"bodymatter\" href=\"chapter_{index:03}.xhtml\">{}</a></li>\n",
                escape_html(&label)
            ));
        }
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html>\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:epub=\"http://www.idpf.org/2007/ops\">\n<head>\n  <meta charset = \"utf-8\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>Table of contents</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n  <nav epub:type = \"toc\" id=\"toc\">\n    <h1 id=\"toc-title\">Table of contents</h1>\n    <ol>\n{items}    </ol>\n  </nav>\n  <nav epub:type = \"landmarks\">\n    <ol>\n{landmarks}    </ol>\n  </nav>\n</body>\n</html>\n"
        )
    } else {
        format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n  <meta name=\"generator\" content=\"crowbook\" />\n  <title>Table of contents</title>\n  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n</head>\n<body>\n  <div id=\"toc\">\n    <h1 id=\"toc-title\">Table of contents</h1>\n    <ol>\n{items}    </ol>\n  </div>\n</body>\n</html>\n"
        )
    }
}

fn render_pdf(book: &Book, output: &OutputPath) -> Result<Vec<Diagnostic>, String> {
    let tex = render_tex_document(book);
    let temp_root = env::temp_dir().join(format!("crowbook-cleanroom-{}", pid_stamp()));
    fs::create_dir_all(&temp_root).map_err(|_| PDF_COMMAND_ERROR.to_string())?;
    let tex_path = temp_root.join("book.tex");
    fs::write(&tex_path, tex).map_err(|_| PDF_COMMAND_ERROR.to_string())?;
    let output_result = Command::new(book.options.get("tex.command").map(String::as_str).unwrap_or("xelatex"))
        .current_dir(&temp_root)
        .arg("book.tex")
        .output();
    let output_data = match output_result {
        Ok(data) => data,
        Err(_) => return Err(PDF_COMMAND_ERROR.to_string()),
    };
    if !output_data.status.success() {
        return Err(PDF_COMMAND_ERROR.to_string());
    }
    let pdf_path = temp_root.join("book.pdf");
    let bytes = fs::read(&pdf_path).map_err(|_| PDF_COMMAND_ERROR.to_string())?;
    let _ = write_binary_output(output, &bytes);
    Ok(Vec::new())
}

fn pid_stamp() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0)
}

fn book_title(book: &Book) -> &str {
    book.options.get("title").map(String::as_str).unwrap_or("")
}

fn book_author(book: &Book) -> &str {
    book.options.get("author").map(String::as_str).unwrap_or("")
}

fn book_lang(book: &Book) -> &str {
    book.options.get("lang").map(String::as_str).unwrap_or("en")
}

fn print_diagnostics(diagnostics: &[Diagnostic], quiet: bool, aggregated: bool) {
    if diagnostics.is_empty() {
        return;
    }
    if aggregated {
        if quiet {
            for diag in diagnostics.iter().filter(|d| d.level == Level::Error) {
                if let Some(detail) = &diag.detailed {
                    eprintln!("[ERROR] {}\n\n{}", diag.text, detail);
                } else {
                    eprintln!("[ERROR] {}", diag.text);
                }
            }
        } else {
            eprintln!("WARNING Crowbook exited successfully, but the following errors occurred:");
            for diag in diagnostics {
                match diag.level {
                    Level::Warning => eprintln!("WARNING {}", diag.text),
                    Level::Error => eprintln!("ERROR {}", diag.text),
                }
            }
        }
        return;
    }

    let visible: Vec<&Diagnostic> = if quiet {
        diagnostics.iter().filter(|d| d.level == Level::Error).collect()
    } else {
        diagnostics.iter().collect()
    };
    if visible.is_empty() {
        return;
    }
    if !quiet {
        eprintln!("WARNING Crowbook exited successfully, but the following errors occurred:");
        for diag in visible {
            match diag.level {
                Level::Warning => eprintln!("WARNING {}", diag.text),
                Level::Error => {
                    if let Some(detail) = &diag.detailed {
                        eprintln!("ERROR {}\n\n{}", diag.text, detail);
                    } else {
                        eprintln!("ERROR {}", diag.text);
                    }
                }
            }
        }
    } else {
        for diag in visible {
            if let Some(detail) = &diag.detailed {
                eprintln!("[ERROR] {}\n\n{}", diag.text, detail);
            } else {
                eprintln!("[ERROR] {}", diag.text);
            }
        }
    }
}

fn render_stats(book: &Book) -> String {
    let mut rows = Vec::new();
    let mut total_chars = 0usize;
    let mut total_words = 0usize;
    for chapter in &book.chapters {
        let raw_html = render_markdown_html(&chapter.content);
        let chars = plain_text_from_html(&raw_html).chars().count();
        let mut body_text = texts_in_tag(&raw_html, "p").join(" ");
        if body_text.is_empty() {
            body_text = plain_text_from_html(&raw_html);
        }
        let words = count_words(&body_text);
        total_chars += chars;
        total_words += words;
        rows.push((chapter.source_name.clone(), chars, words));
    }
    let name_width = rows
        .iter()
        .map(|(name, _, _)| name.len())
        .max()
        .unwrap_or(7)
        .max("Chapter".len());
    let mut out = String::new();
    let _ = writeln!(
        out,
        "{:<name_width$}      Chars      Words  Chars/Word",
        "Chapter",
        name_width = name_width
    );
    out.push_str("---------\n");
    for (name, chars, words) in &rows {
        let ratio = if *words == 0 { 0.0 } else { *chars as f64 / *words as f64 };
        let _ = writeln!(
            out,
            "{:<name_width$}{:>12}{:>11}{:>12.2}",
            name,
            chars,
            words,
            ratio,
            name_width = name_width
        );
    }
    out.push_str("---------\n");
    let total_ratio = if total_words == 0 {
        0.0
    } else {
        total_chars as f64 / total_words as f64
    };
    let _ = writeln!(
        out,
        "{:<name_width$}{:>12}{:>11}{:>12.2}",
        "TOTAL:",
        total_chars,
        total_words,
        total_ratio,
        name_width = name_width
    );
    out.push('\n');
    out
}

fn texts_in_tag(html: &str, tag: &str) -> Vec<String> {
    let mut out = Vec::new();
    let open = format!("<{tag}>");
    let close = format!("</{tag}>");
    let mut rest = html;
    while let Some(start) = rest.find(&open) {
        let after_open = &rest[start + open.len()..];
        if let Some(end) = after_open.find(&close) {
            out.push(plain_text_from_html(&after_open[..end]));
            rest = &after_open[end + close.len()..];
        } else {
            break;
        }
    }
    out
}

fn count_words(text: &str) -> usize {
    text.split_whitespace().count()
}

fn plain_text_from_html(html: &str) -> String {
    let mut out = String::new();
    let mut in_tag = false;
    for ch in html.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => in_tag = false,
            _ if !in_tag => {
                if ch == '\n' || ch == '\r' {
                    continue;
                }
                out.push(ch);
            }
            _ => {}
        }
    }
    html_unescape_basic(out.trim().to_string())
}

fn html_unescape_basic(text: String) -> String {
    text.replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

fn escape_html(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

fn escape_xml(text: &str) -> String {
    escape_html(text)
}

fn escape_json(text: &str) -> String {
    text.replace('\\', "\\\\").replace('"', "\\\"")
}

fn escape_tex(text: &str) -> String {
    text.replace('\\', "\\textbackslash{}")
        .replace('&', "\\&")
        .replace('%', "\\%")
        .replace('$', "\\$")
        .replace('#', "\\#")
        .replace('_', "\\_")
        .replace('{', "\\{")
        .replace('}', "\\}")
        .replace('~', "\\textasciitilde{}")
        .replace('^', "\\textasciicircum{}")
}

fn tex_lang(lang: &str) -> &'static str {
    match lang {
        "fr" => "french",
        "de" => "german",
        "es" => "spanish",
        "it" => "italian",
        _ => "english",
    }
}

fn iso_timestamp() -> String {
    // The real tool uses UTC. A deterministic fallback is enough for the reimplementation.
    "2026-08-09T00:00:00Z".to_string()
}

