VALID_TO = {"epub", "pdf", "html", "tex", "odt", "html.dir"}


@dataclass
class Cli:
    force_emoji: bool = False
    single: bool = False
    no_fancy: bool = False
    verbose: bool = False
    autograph: bool = False
    quiet: bool = False
    create: list[str] | None = None
    output: str | None = None
    to: str | None = None
    set_values: list[str] = field(default_factory=list)
    list_options: bool = False
    runtime_lang: str | None = None
    print_template: str | None = None
    stats: bool = False
    help: bool = False
    version: bool = False
    book: str | None = None


@dataclass
class ChapterSource:
    source_name: str
    content: str


@dataclass
class Book:
    source_path: Path
    base_dir: Path
    options: dict[str, str]
    chapters: list[ChapterSource]


@dataclass
class TocEntry:
    link_id: int
    label: str


@dataclass
class HtmlChapterFile:
    source_name: str
    title: str
    body_html: str


@dataclass
class RenderedBook:
    files: list[HtmlChapterFile] = field(default_factory=list)
    toc_entries: list[TocEntry] = field(default_factory=list)


@dataclass
class RenderState:
    next_link_id: int = 1
    next_para_id: int = 1
    next_chapter_number: int = 1


@dataclass
class Block:
    kind: str
    text: str = ""
    level: int = 0
    items: list[str] = field(default_factory=list)


@dataclass
class Diagnostic:
    level: str
    text: str
    detailed: str | None = None


class ParseError(Exception):
    def __init__(self, text: str) -> None:
        super().__init__(text)
        self.text = text


def main() -> int:
    try:
        cli = parse_args(sys.argv)
    except ParseError as exc:
        sys.stderr.write(exc.text)
        return 2
    return run(cli)


def parse_args(argv: list[str]) -> Cli:
    cli = Cli()
    i = 1
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            i += 1
            while i < len(argv):
                push_positional(cli, argv[i])
                i += 1
            break
        if arg.startswith("--"):
            name = arg[2:]
            if name == "force-emoji":
                cli.force_emoji = True
            elif name == "single":
                cli.single = True
            elif name == "no-fancy":
                cli.no_fancy = True
            elif name == "verbose":
                cli.verbose = True
            elif name == "autograph":
                cli.autograph = True
            elif name == "quiet":
                cli.quiet = True
            elif name == "list-options":
                cli.list_options = True
            elif name == "stats":
                cli.stats = True
            elif name == "help":
                cli.help = True
            elif name == "version":
                cli.version = True
            elif name == "create":
                values, i = collect_multi_values(argv, i + 1)
                if not values:
                    raise ParseError(missing_value("--create <files>..."))
                cli.create = values
                continue
            elif name == "set":
                values, i = collect_multi_values(argv, i + 1)
                if not values:
                    raise ParseError(missing_value("--set <set> <set>..."))
                if len(values) == 1:
                    raise ParseError(
                        "error: 2 values required by '--set <set> <set>...'; only 1 was provided\n\n"
                        "Usage: executable [OPTIONS] [BOOK]\n\n"
                        "For more information, try '--help'.\n"
                    )
                cli.set_values.extend(values)
                continue
            elif name == "output":
                cli.output = expect_value(argv, i + 1, "--output <output>")
                i += 1
            elif name == "to":
                value = expect_value(argv, i + 1, "--to <to>")
                if value not in VALID_TO:
                    raise ParseError(invalid_to(value))
                cli.to = value
                i += 1
            elif name == "lang":
                cli.runtime_lang = expect_value(argv, i + 1, "--lang <lang>")
                i += 1
            elif name == "print-template":
                cli.print_template = expect_value(argv, i + 1, "--print-template <print-template>")
                i += 1
            else:
                raise ParseError(unexpected_arg(arg, tip=True))
            i += 1
            continue
        if arg.startswith("-") and len(arg) > 1:
            chars = list(arg[1:])
            j = 0
            while j < len(chars):
                ch = chars[j]
                if ch == "f":
                    cli.force_emoji = True
                elif ch == "s":
                    cli.single = True
                elif ch == "n":
                    cli.no_fancy = True
                elif ch == "v":
                    cli.verbose = True
                elif ch == "a":
                    cli.autograph = True
                elif ch == "q":
                    cli.quiet = True
                elif ch == "l":
                    cli.list_options = True
                elif ch == "S":
                    cli.stats = True
                elif ch == "h":
                    cli.help = True
                elif ch == "V":
                    cli.version = True
                elif ch == "c":
                    values: list[str] = []
                    if j + 1 < len(chars):
                        values.append("".join(chars[j + 1 :]))
                        j = len(chars)
                    more, i = collect_multi_values(argv, i + 1)
                    values.extend(more)
                    if not values:
                        raise ParseError(missing_value("--create <files>..."))
                    cli.create = values
                    break
                elif ch == "o":
                    if j + 1 < len(chars):
                        cli.output = "".join(chars[j + 1 :])
                    else:
                        cli.output = expect_value(argv, i + 1, "--output <output>")
                        i += 1
                    break
                elif ch == "t":
                    if j + 1 < len(chars):
                        value = "".join(chars[j + 1 :])
                    else:
                        value = expect_value(argv, i + 1, "--to <to>")
                        i += 1
                    if value not in VALID_TO:
                        raise ParseError(invalid_to(value))
                    cli.to = value
                    break
                elif ch == "L":
                    if j + 1 < len(chars):
                        cli.runtime_lang = "".join(chars[j + 1 :])
                    else:
                        cli.runtime_lang = expect_value(argv, i + 1, "--lang <lang>")
                        i += 1
                    break
                else:
                    raise ParseError(unexpected_arg(f"-{ch}", tip=True))
                j += 1
            i += 1
            continue
        push_positional(cli, arg)
        i += 1
    if cli.output is not None and cli.to is None:
        raise ParseError(
            "error: the following required arguments were not provided:\n"
            "  --to <to>\n\n"
            "Usage: executable --to <to> --output <output> <BOOK>\n\n"
            "For more information, try '--help'.\n"
        )
    return cli


def push_positional(cli: Cli, value: str) -> None:
    if cli.book is not None:
        raise ParseError(unexpected_arg(value, tip=False))
    cli.book = value


def collect_multi_values(argv: list[str], start: int) -> tuple[list[str], int]:
    values: list[str] = []
    index = start
    while index < len(argv) and not argv[index].startswith("-"):
        values.append(argv[index])
        index += 1
    return values, index


def expect_value(argv: list[str], index: int, display: str) -> str:
    if index >= len(argv) or argv[index].startswith("-"):
        raise ParseError(missing_value(display))
    return argv[index]


def missing_value(display: str) -> str:
    return f"error: a value is required for '{display}' but none was supplied\n\nFor more information, try '--help'.\n"


def invalid_to(value: str) -> str:
    return (
        f"error: invalid value '{value}' for '--to <to>'\n"
        "  [possible values: epub, pdf, html, tex, odt, html.dir]\n\n"
        "For more information, try '--help'.\n"
    )


def unexpected_arg(arg: str, *, tip: bool) -> str:
    out = f"error: unexpected argument '{arg}' found\n\n"
    if tip:
        out += f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
    out += "Usage: executable [OPTIONS] [BOOK]\n\nFor more information, try '--help'.\n"
    return out


def run(cli: Cli) -> int:
    if cli.help:
        sys.stdout.write(HELP_TEXT)
        return 0
    if cli.version:
        print(VERSION)
        return 0

    if cli.create is not None:
        maybe_banner(cli.quiet)
        sys.stdout.write(CREATE_TEMPLATE_HEAD)
        for path in cli.create:
            print(f"+ {path}")
        return 0

    if cli.list_options:
        maybe_banner(cli.quiet)
        sys.stdout.write(LIST_OPTIONS_TEXT)
        return 0

    if cli.print_template is not None:
        maybe_banner(cli.quiet)
        text = TEMPLATE_TEXTS.get(cli.print_template)
        if text is None:
            sys.stderr.write(f"ERROR {cli.print_template} is not a valid template name\n")
        else:
            sys.stdout.write(text)
        return 0

    if cli.book is None:
        maybe_banner(cli.quiet)
        sys.stderr.write(
            "ERROR You must pass the name of a book configuration file.\n"
            "For more information try --help.\n"
        )
        return 0

    maybe_banner(cli.quiet)

    source_path = Path(cli.book)
    try:
        book = load_single_book(source_path) if cli.single else load_book_config(source_path)
    except RuntimeError as exc:
        sys.stderr.write(f"ERROR {exc}\n")
        return 0

    if cli.autograph:
        sys.stdout.write("Enter autograph:\n")
        sys.stdout.flush()
        autograph = sys.stdin.readline().rstrip("\n")
        book.options["autograph"] = autograph

    if cli.set_values:
        if len(cli.set_values) % 2 != 0:
            sys.stderr.write(
                "ERROR An odd number of arguments was passed to --set, but it takes\n"
                "a list of key value pairs.\n"
            )
            return 0
        try:
            apply_set_values(book, cli.set_values)
        except RuntimeError as exc:
            sys.stderr.write(f"ERROR {exc}\n")
            return 0

    if cli.stats:
        sys.stdout.write(render_stats(book))
        return 0

    rendered = render_book(book)

    if cli.to is not None:
        render_explicit_target(cli, book, rendered)
        return 0

    targets = implicit_targets(book)
    if not targets:
        return 0
    diagnostics = render_implicit_targets(cli, book, rendered, targets)
    print_diagnostics(diagnostics, quiet=cli.quiet, aggregated=True)
    return 0


def maybe_banner(quiet: bool) -> None:
    if not quiet:
        sys.stderr.write(f"{BANNER}\n")


KNOWN_KEYS: set[str] | None = None


def known_option_keys() -> set[str]:
    global KNOWN_KEYS
    if KNOWN_KEYS is not None:
        return KNOWN_KEYS
    keys: set[str] = set()
    for line in LIST_OPTIONS_TEXT.splitlines():
        if not line or line.startswith(" "):
            continue
        if " " in line:
            continue
        if all(c.isupper() or c in "[]#()_: " for c in line):
            continue
        keys.add(line)
    keys.add("output.odt")
    KNOWN_KEYS = keys
    return keys


def load_single_book(path: Path) -> Book:
    if not path.exists():
        raise RuntimeError(f"{path}: Could not find file '{path}' for book chapter")
    content = path.read_text(encoding="utf-8")
    options, markdown = split_front_matter(content)
    return Book(
        source_path=path,
        base_dir=path.parent if path.parent != Path("") else Path("."),
        options=options,
        chapters=[ChapterSource(source_name=path.name, content=markdown)],
    )


def load_book_config(path: Path) -> Book:
    if not path.exists():
        raise RuntimeError(f"Could not find file '{path}' for book")
    text = path.read_text(encoding="utf-8")
    base_dir = path.parent if path.parent != Path("") else Path(".")
    options: dict[str, str] = {}
    chapters: list[ChapterSource] = []
    for line_number, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("+"):
            rel = line[1:].strip()
            chapter_path = base_dir / rel
            if not chapter_path.exists():
                raise RuntimeError(f"{path}:{line_number}: Could not find file '{rel}' for book chapter")
            chapters.append(
                ChapterSource(source_name=rel, content=chapter_path.read_text(encoding="utf-8"))
            )
            continue
        key, value = split_option_line(line)
        if key not in known_option_keys():
            raise RuntimeError(f"{path}:{line_number}: Error converting BookOption: unrecognized key '{key}'")
        options[key] = value
    return Book(source_path=path, base_dir=base_dir, options=options, chapters=chapters)


def split_front_matter(content: str) -> tuple[dict[str, str], str]:
    options: dict[str, str] = {}
    if not content.startswith("---\n"):
        return options, content
    rest = content[4:]
    end = rest.find("\n---")
    if end == -1:
        return options, content
    block = rest[:end]
    for raw in block.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        key, value = split_option_line(line)
        options[key] = value
    after = rest[end + 4 :]
    if after.startswith("\n"):
        after = after[1:]
    return options, after


def split_option_line(line: str) -> tuple[str, str]:
    key, value = line.split(":", 1)
    return key.strip(), value.strip()


def apply_set_values(book: Book, values: list[str]) -> None:
    keys = known_option_keys()
    book_name = book.source_path.name or "book.book"
    for key, value in zip(values[0::2], values[1::2]):
        if key not in keys:
            raise RuntimeError(
                f"Error in setting key {key}: {book_name}:3: Error converting BookOption: unrecognized key '{key}'"
            )
        book.options[key] = value


def parse_output_list(value: str) -> list[str]:
    inner = value.strip()
    if inner.startswith("[") and inner.endswith("]"):
        inner = inner[1:-1]
    return [item.strip() for item in inner.split(",") if item.strip()]


def book_title(book: Book) -> str:
    return book.options.get("title", "")


def book_author(book: Book) -> str:
    return book.options.get("author", "")


def book_lang(book: Book) -> str:
    return book.options.get("lang", "en")


def resolve_book_output_path(book: Book, value: str) -> Path:
    path = Path(value)
    if path.is_absolute():
        out = path
    else:
        out = book.base_dir / path
    base = book.options.get("output.base_path", "")
    if base and not path.is_absolute():
        out = book.base_dir / base / path
    return out


def default_book_output_file(book: Book, extension: str) -> Path:
    return resolve_book_output_path(book, f"{book.source_path.stem}.{extension}")


def implicit_targets(book: Book) -> list[tuple[str, tuple[str, Path | None]]]:
    targets: list[tuple[str, tuple[str, Path | None]]] = []
    if "output.html" in book.options:
        targets.append(("html", ("file", resolve_book_output_path(book, book.options["output.html"]))))
    if "output.epub" in book.options:
        targets.append(("epub", ("file", resolve_book_output_path(book, book.options["output.epub"]))))
    if "output.tex" in book.options:
        targets.append(("tex", ("file", resolve_book_output_path(book, book.options["output.tex"]))))
    if "output.pdf" in book.options:
        targets.append(("pdf", ("file", resolve_book_output_path(book, book.options["output.pdf"]))))
    if "output.html.dir" in book.options:
        targets.append(
            ("html.dir", ("dir", resolve_book_output_path(book, book.options["output.html.dir"])))
        )
    if "output" in book.options:
        names = parse_output_list(book.options["output"])
        have = {name for name, _ in targets}
        for name in names:
            if name in have:
                continue
            if name == "html":
                targets.append(("html", ("file", default_book_output_file(book, "html"))))
            elif name == "epub":
                targets.append(("epub", ("file", default_book_output_file(book, "epub"))))
            elif name == "tex":
                targets.append(("tex", ("file", default_book_output_file(book, "tex"))))
            elif name == "pdf":
                targets.append(("pdf", ("file", default_book_output_file(book, "pdf"))))
            elif name == "html.dir":
                targets.append(("html.dir", ("dir", book.base_dir / "auto")))
    return targets


def render_explicit_target(cli: Cli, book: Book, rendered: RenderedBook) -> None:
    target = cli.to
    assert target is not None
    if target == "html.dir":
        output = (
            ("dir", Path(cli.output))
            if cli.output is not None
            else (
                ("dir", resolve_book_output_path(book, book.options["output.html.dir"]))
                if "output.html.dir" in book.options
                else ("stream", None)
            )
        )
        if output[0] == "stream":
            sys.stderr.write(
                "ERROR Error during rendering: can only render HTML directory to a path, not to a stream\n"
            )
            return
        diagnostics = render_html_dir(book, rendered, output)
        print_diagnostics(diagnostics, quiet=cli.quiet, aggregated=False)
        return

    if cli.output is not None:
        output = ("file", Path(cli.output))
    elif target == "html" and "output.html" in book.options:
        output = ("file", resolve_book_output_path(book, book.options["output.html"]))
    elif target == "epub" and "output.epub" in book.options:
        output = ("file", resolve_book_output_path(book, book.options["output.epub"]))
    elif target == "tex" and "output.tex" in book.options:
        output = ("file", resolve_book_output_path(book, book.options["output.tex"]))
    elif target == "pdf" and "output.pdf" in book.options:
        output = ("file", resolve_book_output_path(book, book.options["output.pdf"]))
    else:
        output = ("stream", None)

    if target == "html":
        write_text_output(output, render_html_document(book, rendered))
    elif target == "tex":
        write_text_output(output, render_tex_document(book))
    elif target == "epub":
        epub_bytes, diagnostics = render_epub_bytes(book, rendered)
        write_binary_output(output, epub_bytes)
        print_diagnostics(diagnostics, quiet=cli.quiet, aggregated=False)
    elif target == "pdf":
        try:
            diagnostics = render_pdf(book, output)
            print_diagnostics(diagnostics, quiet=cli.quiet, aggregated=False)
        except RuntimeError as exc:
            sys.stderr.write(f"ERROR {exc}\n")
    elif target == "odt":
        sys.stderr.write("ERROR unknown format odt\n")


def render_implicit_targets(
    cli: Cli, book: Book, rendered: RenderedBook, targets: list[tuple[str, tuple[str, Path | None]]]
) -> list[Diagnostic]:
    diagnostics: list[Diagnostic] = []
    for target, output in targets:
        if target == "html":
            write_text_output(output, render_html_document(book, rendered))
        elif target == "tex":
            write_text_output(output, render_tex_document(book))
        elif target == "epub":
            epub_bytes, diags = render_epub_bytes(book, rendered)
            write_binary_output(output, epub_bytes)
            diagnostics.extend(diags)
        elif target == "pdf":
            try:
                diagnostics.extend(render_pdf(book, output))
            except RuntimeError as exc:
                diagnostics.append(Diagnostic("error", f"Error rendering pdf: {exc}"))
        elif target == "html.dir":
            diags = render_html_dir(book, rendered, output)
            for diag in diags:
                detail = HTML_DIR_TEMPLATE_ERROR if cli.quiet else None
                diagnostics.append(
                    Diagnostic("error", f"Error rendering html.dir: {diag.text}", detailed=detail)
                )
    return diagnostics


def write_text_output(output: tuple[str, Path | None], text: str) -> None:
    kind, path = output
    if kind == "stream":
        sys.stdout.write(text)
        return
    assert path is not None
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def write_binary_output(output: tuple[str, Path | None], data: bytes) -> None:
    kind, path = output
    if kind == "stream":
        sys.stdout.buffer.write(data)
        return
    assert path is not None
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)


def parse_markdown_blocks(markdown: str) -> list[Block]:
    lines = markdown.splitlines()
    blocks: list[Block] = []
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue
        if stripped.startswith("```"):
            fence = stripped[:3]
            code: list[str] = []
            i += 1
            while i < len(lines) and not lines[i].strip().startswith(fence):
                code.append(lines[i])
                i += 1
            if i < len(lines):
                i += 1
            blocks.append(Block(kind="code", text="\n".join(code)))
            continue
        match = re.match(r"^(#{1,6})\s+(.*)$", line)
        if match:
            blocks.append(Block(kind="heading", level=len(match.group(1)), text=match.group(2).strip()))
            i += 1
            continue
        if re.match(r"^[-*_]{3,}\s*$", stripped):
            blocks.append(Block(kind="hr"))
            i += 1
            continue
        if stripped.startswith(">"):
            quote_lines: list[str] = []
            while i < len(lines) and lines[i].strip().startswith(">"):
                quote_lines.append(lines[i].split(">", 1)[1].lstrip())
                i += 1
            blocks.append(Block(kind="blockquote", text=" ".join(x.strip() for x in quote_lines if x.strip())))
            continue
        if re.match(r"^\s*[-*+]\s+", line):
            items: list[str] = []
            while i < len(lines) and re.match(r"^\s*[-*+]\s+", lines[i]):
                items.append(re.sub(r"^\s*[-*+]\s+", "", lines[i]).strip())
                i += 1
            blocks.append(Block(kind="ul", items=items))
            continue
        if re.match(r"^\s*\d+\.\s+", line):
            items = []
            while i < len(lines) and re.match(r"^\s*\d+\.\s+", lines[i]):
                items.append(re.sub(r"^\s*\d+\.\s+", "", lines[i]).strip())
                i += 1
            blocks.append(Block(kind="ol", items=items))
            continue
        para_lines = [stripped]
        i += 1
        while i < len(lines):
            nxt = lines[i].strip()
            if not nxt:
                break
            if (
                re.match(r"^(#{1,6})\s+", lines[i])
                or re.match(r"^[-*_]{3,}\s*$", nxt)
                or nxt.startswith(">")
                or nxt.startswith("```")
                or re.match(r"^\s*[-*+]\s+", lines[i])
                or re.match(r"^\s*\d+\.\s+", lines[i])
            ):
                break
            para_lines.append(nxt)
            i += 1
        blocks.append(Block(kind="paragraph", text=" ".join(para_lines)))
    return blocks


def render_inline(text: str) -> str:
    placeholders: dict[str, str] = {}

    def stash(value: str) -> str:
        key = f"\0{len(placeholders)}\0"
        placeholders[key] = value
        return key

    escaped = html.escape(text, quote=True)
    escaped = re.sub(
        r"`([^`]+)`",
        lambda m: stash(f"<code>{m.group(1)}</code>"),
        escaped,
    )
    escaped = re.sub(
        r"\[([^\]]+)\]\(([^)]+)\)",
        lambda m: stash(f'<a href = "{html.escape(m.group(2), quote=True)}">{render_inline(m.group(1))}</a>'),
        escaped,
    )
    escaped = re.sub(r"\*\*([^*]+)\*\*", lambda m: f"<strong>{m.group(1)}</strong>", escaped)
    escaped = re.sub(r"\*([^*]+)\*", lambda m: f"<em>{m.group(1)}</em>", escaped)
    for key, value in placeholders.items():
        escaped = escaped.replace(key, value)
    return escaped


def plain_inline(text: str) -> str:
    text = re.sub(r"\[([^\]]+)\]\(([^)]+)\)", r"\1", text)
    text = re.sub(r"`([^`]+)`", r"\1", text)
    text = text.replace("**", "").replace("*", "")
    return text


def render_book(book: Book) -> RenderedBook:
    state = RenderState()
    rendered = RenderedBook()
    for index, chapter in enumerate(book.chapters):
        blocks = parse_markdown_blocks(chapter.content)
        first_title = ""
        toc_entries: list[TocEntry] = []
        parts: list[str] = []
        found_h1 = False
        for block in blocks:
            if block.kind == "heading":
                inner = render_inline(block.text)
                if block.level == 1:
                    found_h1 = True
                    chapter_number = state.next_chapter_number
                    link_id = state.next_link_id
                    state.next_chapter_number += 1
                    state.next_link_id += 1
                    plain = plain_inline(block.text)
                    if not first_title:
                        first_title = plain
                    label = f"{chapter_number}. {plain}" if plain else f"{chapter_number}."
                    toc_entries.append(TocEntry(link_id=link_id, label=label))
                    if inner:
                        parts.append(
                            f"  <h1 id = 'link-{link_id}'><span class = 'chapter-header'>Chapter {chapter_number}</span><br />{inner}</h1>"
                        )
                    else:
                        parts.append(
                            f"  <h1 id = 'link-{link_id}'><span class = 'chapter-header'>Chapter {chapter_number}</span></h1>"
                        )
                else:
                    link_id = state.next_link_id
                    state.next_link_id += 1
                    parts.append(f'<h{block.level} id = "link-{link_id}">{inner}</h{block.level}>')
            elif block.kind == "paragraph":
                para_id = state.next_para_id
                state.next_para_id += 1
                parts.append(f'<p id = "para-{para_id}">{render_inline(block.text)}</p>')
            elif block.kind == "blockquote":
                parts.append(f"<blockquote>{render_inline(block.text)}</blockquote>")
            elif block.kind == "code":
                parts.append(f"<pre><code>{html.escape(block.text, quote=True)}</code></pre>")
            elif block.kind == "ul":
                items = "".join(f"<li>{render_inline(item)}</li>" for item in block.items)
                parts.append(f"<ul>{items}</ul>")
            elif block.kind == "ol":
                items = "".join(f"<li>{render_inline(item)}</li>" for item in block.items)
                parts.append(f"<ol>{items}</ol>")
            elif block.kind == "hr":
                parts.append('<p class = "rule">***</p>')
        if not found_h1:
            chapter_number = state.next_chapter_number
            link_id = state.next_link_id
            state.next_chapter_number += 1
            state.next_link_id += 1
            parts.insert(
                0,
                f"  <h1 id = 'link-{link_id}'><span class = 'chapter-header'>Chapter {chapter_number}</span></h1>",
            )
            toc_entries.append(TocEntry(link_id=link_id, label=f"{chapter_number}."))
        rendered.toc_entries.extend(toc_entries)
        rendered.files.append(
            HtmlChapterFile(
                source_name=chapter.source_name,
                title=first_title,
                body_html=f'<div id = "chapter-{index}" class = "chapter">\n' + "\n".join(parts) + "\n</div>",
            )
        )
    return rendered


def json_ld(book: Book) -> str:
    return (
        "<script type = 'application/ld+json'>\n"
        "{\n"
        '    "@context": "http://schema.org/",\n'
        '    "@type": "Book",\n'
        f'    "author": "{escape_json(book_author(book))}",\n'
        f'    "name": "{escape_json(book_title(book))}",\n'
        "    \n"
        "    \n"
        "    \n"
        "    \n"
        "    \n"
        f'    "inLanguage": "{escape_json(book_lang(book))}"\n'
        "}\n"
        "</script>"
    )


def render_html_document(book: Book, rendered: RenderedBook) -> str:
    title = html.escape(book_title(book), quote=True)
    author = html.escape(book_author(book), quote=True)
    subtitle = html.escape(book.options.get("subtitle", ""), quote=True)
    lang = html.escape(book_lang(book), quote=True)
    autograph = html.escape(book.options.get("autograph", ""), quote=True)
    has_toc = len(rendered.toc_entries) > 1
    out = io.StringIO()
    out.write(
        f'<!DOCTYPE html>\n<html lang="{lang}">\n  <head>\n'
        '    <meta charset="utf-8">\n'
        '    <meta name="generator" content="crowbook">\n'
        '    <meta name="viewport" content="width=device-width">\n'
        f'    <meta name="author" content="{author}">\n'
        "    \n"
        f"    <title>{title}</title>\n"
        '    <style type = "text/css">\n'
        f"      {HTML_CSS}"
        "    </style>\n"
        '    <style type = "text/css" media = "print">\n'
        f"      {HTML_PRINT_CSS}"
        "    </style>\n"
        "   <script>\n"
        f"{HTML_JS}"
        "   </script>\n\n\n"
        "  </head>\n"
        "  <body>\n"
        f"    {json_ld(book)}\n"
    )
    if has_toc:
        out.write(
            '    <nav id = "nav">\n'
            "      \n"
            '      <div id = "nav-title">\n'
            f'        <h2><a href = "#link-0">{title}</a></h2>\n'
            "      </div>\n"
            "          <ul>\n"
        )
        for entry in rendered.toc_entries:
            out.write(f'      <li><a href="#link-{entry.link_id}">{html.escape(entry.label, quote=True)}</a></li>\n')
        out.write("    </ul>\n    </nav>\n\n")
    out.write(
        '    <div id = "content">\n'
        "      \n"
        '      <div id = "page">\n'
        "        <header>\n\n"
        '          <div id = "menu">\n'
    )
    if has_toc:
        out.write(
            "\t        \n"
            '            <img id = "menu-button" onclick="toggle();"\n'
            f'                 src="{MENU_SVG}"\n'
            '                 alt = "Table of contents" title = "Table of contents" />\n'
            "          \n"
        )
    else:
        out.write("\t        \n")
    out.write(
        "          </div>\n"
        f'\t  <h2 class="author">{author}</h2>\n'
        f'          <h1 id = "link-0" class="title" >{title}</h1>\n'
    )
    if subtitle:
        out.write(f'\t  <h2 class = "subtitle">{subtitle}</h2>\n')
    else:
        out.write("\t  \n")
    if autograph:
        out.write(
            "\t  \n"
            '\t  <div id = "autograph">\n'
            f"\t    {autograph}\n"
            "\t  </div>\n"
        )
    else:
        out.write("\t  \n")
    out.write("\t  \n        </header>\n\n")
    for file in rendered.files:
        out.write(file.body_html)
        out.write("\n")
    out.write("\n      </div>\n      \n    </div>\n  </body>\n</html>\n")
    return out.getvalue()


def strip_chapter_wrapper(body_html: str) -> str:
    lines = body_html.splitlines()
    if len(lines) >= 3:
        return "\n".join(lines[1:-1])
    return body_html


def render_html_dir(book: Book, rendered: RenderedBook, output: tuple[str, Path | None]) -> list[Diagnostic]:
    _, path = output
    assert path is not None
    path.mkdir(parents=True, exist_ok=True)
    (path / "stylesheet.css").write_text(HTML_CSS, encoding="utf-8")
    (path / "print.css").write_text(HTML_PRINT_CSS, encoding="utf-8")
    for index, file in enumerate(rendered.files):
        (path / f"chapter_{index:03}.html").write_text(
            render_html_dir_page(book, rendered, file, index), encoding="utf-8"
        )
    return [Diagnostic("error", HTML_DIR_TEMPLATE_ERROR)]


def render_html_dir_page(book: Book, rendered: RenderedBook, file: HtmlChapterFile, index: int) -> str:
    lang = html.escape(book_lang(book), quote=True)
    author = html.escape(book_author(book), quote=True)
    title = html.escape(book_title(book), quote=True)
    chapter_label = f"{index + 1}. {file.title}" if file.title else f"{index + 1}"
    toc = "".join(
        f'      <li><a href="chapter_{i:03}.html">{html.escape((f"{i + 1}. {f.title}" if f.title else str(i + 1)), quote=True)}</a></li>\n'
        for i, f in enumerate(rendered.files)
    )
    return (
        f'<!DOCTYPE html>\n<html lang="{lang}">\n  <head>\n'
        '    <meta charset="utf-8">\n'
        '    <meta name="generator" content="crowbook">\n'
        f'    <meta name="author" content="{author}">\n'
        '    <meta name="viewport" content="width=device-width">\n'
        "    \n"
        f"    <title>{title} - {html.escape(chapter_label, quote=True)}</title>\n"
        '    <link rel = "stylesheet" href = "stylesheet.css" type = "text/css"\n'
        "          />\n"
        '    <link rel = "stylesheet" href = "print.css" type = "text/css"\n'
        '          media = "print" />\n'
        "    \n"
        "   <script>\n"
        f"{HTML_JS}"
        "   </script>\n\n\n"
        "  </head>  \n"
        "  <body>\n"
        f"  {json_ld(book)}\n"
        '  <nav id = "nav">\n'
        f'    <h2><a href = "index.html">{title}</a></h2>\n'
        "        <ul>\n"
        f"{toc}"
        "    </ul>\n"
        "  </nav>\n"
        '  <div id = "content">\n'
        '    <div id = "page">\n'
        f"{file.body_html}\n"
        "    </div>\n"
        "  </div>\n"
        "  </body>\n"
        "</html>\n"
    )


def render_tex_document(book: Book) -> str:
    title = escape_tex(book_title(book))
    author = escape_tex(book_author(book))
    lang = tex_lang(book_lang(book))
    body = io.StringIO()
    chapter_index = 0
    for chapter in book.chapters:
        blocks = parse_markdown_blocks(chapter.content)
        for block in blocks:
            if block.kind == "heading" and block.level == 1:
                body.write(f"\\chapter{{{escape_tex(plain_inline(block.text))}}}\n")
                body.write(f"\\label{{chapter-{chapter_index}}}\n")
                chapter_index += 1
            elif block.kind == "heading" and block.level == 2:
                body.write(f"\\section{{{escape_tex(plain_inline(block.text))}}}\n")
            elif block.kind == "heading" and block.level == 3:
                body.write(f"\\subsection{{{escape_tex(plain_inline(block.text))}}}\n")
            elif block.kind == "paragraph":
                body.write(f"{escape_tex(plain_inline(block.text))}\n\n")
            elif block.kind == "blockquote":
                body.write(f"\\begin{{quotation}}\n{escape_tex(plain_inline(block.text))}\n\\end{{quotation}}\n\n")
            elif block.kind == "code":
                body.write(f"\\begin{{verbatim}}\n{block.text}\n\\end{{verbatim}}\n\n")
            elif block.kind in {"ul", "ol"}:
                env = "itemize" if block.kind == "ul" else "enumerate"
                body.write(f"\\begin{{{env}}}\n")
                for item in block.items:
                    body.write(f"\\item {escape_tex(plain_inline(item))}\n")
                body.write(f"\\end{{{env}}}\n\n")
    return (
        "\\documentclass{book}\n\n"
        "%% Package inclusion\n\n"
        "% Unicode support if xelatex is used\n"
        "\\usepackage{fontspec}\n"
        "\\usepackage{xunicode}\n\n\n"
        f"\\usepackage[{lang}]{{babel}} % Language support\n"
        "\\usepackage{fancyhdr} % Headers\n"
        "\\usepackage{enumitem}\n\n"
        "% Allows hyphenatations in \\texttt\n"
        "\\usepackage[htt]{hyphenat}\n\n\n\n"
        "% Set hyperlinks and metadata\n"
