def render_epub_bytes(book: Book, rendered: RenderedBook) -> tuple[bytes, list[Diagnostic]]:
    diagnostics: list[Diagnostic] = []
    if shutil.which("zip") is None:
        diagnostics.append(Diagnostic("warning", EPUB_WARNING))
    version = 2
    try:
        version = int(book.options.get("epub.version", "2"))
    except ValueError:
        version = 2
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        zf.writestr("mimetype", "application/epub+zip", compress_type=zipfile.ZIP_STORED)
        zf.writestr("META-INF/container.xml", container_xml())
        zf.writestr("META-INF/com.apple.ibooks.display-options.xml", ibooks_display_options())
        zf.writestr("OEBPS/title_page.xhtml", epub_title_page(book, version))
        for index, file in enumerate(rendered.files):
            zf.writestr(f"OEBPS/chapter_{index:03}.xhtml", epub_chapter_page(book, file, index, version))
        zf.writestr("OEBPS/stylesheet.css", EPUB_CSS)
        zf.writestr("OEBPS/content.opf", epub_content_opf(book, rendered, version))
        zf.writestr("OEBPS/toc.ncx", epub_toc_ncx(rendered))
        zf.writestr("OEBPS/nav.xhtml", epub_nav(book, rendered, version))
    return buf.getvalue(), diagnostics


