def epub_content_opf(book: Book, rendered: RenderedBook, version: int) -> str:
    title = html.escape(book_title(book), quote=True)
    lang = html.escape(book_lang(book), quote=True)
    manifest = [
        '    <item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/>',
        '    <item id="nav" href="nav.xhtml" media-type="application/xhtml+xml"' + (' properties="nav"/>' if version >= 3 else "/>"),
        '    <item media-type="application/xhtml+xml" id="id_title_page.xhtml" href="title_page.xhtml"/>',
    ]
    spine = ['    <itemref idref="id_title_page.xhtml"/>']
    guide = [
        '    <reference type="toc" title="Table of contents" href="nav.xhtml"/>',
        '    <reference type="title-page" title="Title" href="title_page.xhtml"/>',
    ]
    for index, file in enumerate(rendered.files):
        manifest.append(
            f'    <item media-type="application/xhtml+xml" id="id_chapter_{index:03}.xhtml" href="chapter_{index:03}.xhtml"/>'
        )
        spine.append(f'    <itemref idref="id_chapter_{index:03}.xhtml"/>')
        label = html.escape(f"{index + 1}. {file.title}" if file.title else str(index + 1), quote=True)
        guide.append(
            f'    <reference type="text" title="{label}" href="chapter_{index:03}.xhtml"/>'
        )
    manifest.append('    <item media-type="text/css" id="id_stylesheet.css" href="stylesheet.css"/>')
    if version >= 3:
        return (
            '<?xml version="1.0" encoding="UTF-8"?>\n'
            '<package version="3.0" xmlns="http://www.idpf.org/2007/opf" unique-identifier="epub-id-1">\n'
            '  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/"\n'
            '            xmlns:opf="http://www.idpf.org/2007/opf">\n'
            '    <dc:identifier id="epub-id-1">urn:uuid:00000000-0000-0000-0000-000000000000</dc:identifier>\n'
            f"    <dc:title>{title}</dc:title>\n"
            "    \n"
            "    \n"
            f'    <dc:language id="epub-creator-0">{lang}</dc:language>\n'
            "    \n"
            "    \n"
            '    <meta property="dcterms:modified">2026-08-09T00:00:00Z</meta>\n\n'
            "  </metadata>\n"
            "  <manifest>\n"
            + "\n".join(manifest)
            + "\n  </manifest>\n"
            '  <spine toc="ncx" page-progression-direction="ltr">\n'
            + "\n".join(spine)
            + "\n  </spine>\n"
            "  <guide>\n"
            + "\n".join(guide)
            + "\n  </guide>\n"
            "</package>\n"
        )
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<package version="2.0" xmlns="http://www.idpf.org/2007/opf" unique-identifier="epub-id-1">\n'
        '  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/"\n'
        '            xmlns:opf="http://www.idpf.org/2007/opf">\n'
        '    <dc:identifier id="epub-id-1">urn:uuid:00000000-0000-0000-0000-000000000000</dc:identifier>\n'
        f"    <dc:title>{title}</dc:title>\n"
        "    \n"
        "    \n"
        f"    <dc:language>{lang}</dc:language>\n"
        "    \n"
        "    \n\n"
        "  </metadata>\n"
        "  <manifest>\n"
        + "\n".join(manifest)
        + "\n  </manifest>\n"
        '  <spine toc="ncx">\n'
        + "\n".join(spine)
        + "\n  </spine>\n"
        "  <guide>\n"
        + "\n".join(guide)
        + "\n  </guide>\n"
        "</package>\n"
    )


def epub_toc_ncx(rendered: RenderedBook) -> str:
    points = [
        '    <navPoint playOrder="1" id="navPoint-1">\n'
        "      <navLabel>\n"
        "       <text>Title</text>\n"
        "      </navLabel>\n"
        '      <content src="title_page.xhtml"/>\n'
        "    </navPoint>"
    ]
    for index, file in enumerate(rendered.files, start=2):
        label = html.escape(f"{index - 1}. {file.title}" if file.title else str(index - 1), quote=True)
        points.append(
            f'    <navPoint playOrder="{index}" id="navPoint-{index}">\n'
            "      <navLabel>\n"
            f"       <text>{label}</text>\n"
            "      </navLabel>\n"
            f'      <content src="chapter_{index - 2:03}.xhtml"/>\n'
            "    </navPoint>"
        )
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<ncx version="2005-1" xmlns="http://www.daisy.org/z3986/2005/ncx/">\n'
        "  <head>\n"
        '    <meta name="dtb:depth" content="1" />\n'
