        "    <text>Table of contents</text>\n"
        "  </docTitle>\n"
        "  <navMap>\n"
        + "\n".join(points)
        + "\n  </navMap>\n"
        "</ncx>\n"
    )


def epub_nav(book: Book, rendered: RenderedBook, version: int) -> str:
    items = ['      <li><a href="title_page.xhtml">Title</a></li>']
    for index, file in enumerate(rendered.files):
        label = html.escape(f"{index + 1}. {file.title}" if file.title else str(index + 1), quote=True)
        items.append(f'      <li><a href="chapter_{index:03}.xhtml">{label}</a></li>')
    if version >= 3:
        landmarks = ['      <li><a epub:type="titlepage" href="title_page.xhtml">Title</a></li>']
        for index, file in enumerate(rendered.files):
            label = html.escape(f"{index + 1}. {file.title}" if file.title else str(index + 1), quote=True)
            landmarks.append(
                f'      <li><a epub:type="bodymatter" href="chapter_{index:03}.xhtml">{label}</a></li>'
            )
        return (
            '<?xml version="1.0" encoding="UTF-8"?>\n'
            "<!DOCTYPE html>\n"
            '<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">\n'
            "<head>\n"
            '  <meta charset = "utf-8" />\n'
            '  <meta name="generator" content="crowbook" />\n'
            "  <title>Table of contents</title>\n"
            '  <link rel="stylesheet" type="text/css" href="stylesheet.css" />\n'
            "</head>\n"
            "<body>\n"
            '  <nav epub:type = "toc" id="toc">\n'
            '    <h1 id="toc-title">Table of contents</h1>\n'
            "    <ol>\n"
            + "\n".join(items)
            + "\n    </ol>\n"
            "  </nav>\n"
            '  <nav epub:type = "landmarks">\n'
