        '  <meta name="generator" content="crowbook" />\n'
        "  <title>Table of contents</title>\n"
        '  <link rel="stylesheet" type="text/css" href="stylesheet.css" />\n'
        "</head>\n"
        "<body>\n"
        '  <div id="toc">\n'
        '    <h1 id="toc-title">Table of contents</h1>\n'
        "    <ol>\n"
        + "\n".join(items)
        + "\n    </ol>\n"
        "  </div>\n"
        "</body>\n"
        "</html>\n"
    )


def render_pdf(book: Book, output: tuple[str, Path | None]) -> list[Diagnostic]:
    tex = render_tex_document(book)
    command = book.options.get("tex.command", "xelatex")
    with tempfile.TemporaryDirectory(prefix="crowbook-cleanroom-") as tmp:
        tmp_path = Path(tmp)
        tex_path = tmp_path / "book.tex"
        tex_path.write_text(tex, encoding="utf-8")
        try:
            proc = subprocess.run(
                [command, "book.tex"],
                cwd=tmp_path,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=False,
            )
        except FileNotFoundError as exc:
            raise RuntimeError(PDF_COMMAND_ERROR) from exc
        if proc.returncode != 0:
            raise RuntimeError(PDF_COMMAND_ERROR)
        pdf_path = tmp_path / "book.pdf"
        if not pdf_path.exists():
            raise RuntimeError(PDF_COMMAND_ERROR)
        write_binary_output(output, pdf_path.read_bytes())
    return []


def render_stats(book: Book) -> str:
    rows: list[tuple[str, int, int]] = []
    total_chars = 0
    total_words = 0
    for chapter in book.chapters:
        blocks = parse_markdown_blocks(chapter.content)
        char_count = 0
        heading_words = 0
        body_words = 0
        for block in blocks:
            if block.kind == "heading":
                plain = plain_inline(block.text)
                char_count += len(plain)
                heading_words += len(plain.split())
            elif block.kind == "paragraph":
                plain = plain_inline(block.text)
                char_count += len(plain)
                body_words += len(plain.split())
            elif block.kind == "blockquote":
                plain = plain_inline(block.text)
                char_count += len(plain)
                body_words += len(plain.split())
            elif block.kind in {"ul", "ol"}:
                for item in block.items:
                    plain = plain_inline(item)
                    char_count += len(plain)
                    body_words += len(plain.split())
            elif block.kind == "code":
                char_count += len(block.text)
                body_words += len(block.text.split())
        word_count = body_words if body_words else heading_words
        rows.append((chapter.source_name, char_count, word_count))
        total_chars += char_count
        total_words += word_count
    name_width = max([len("Chapter")] + [len(name) for name, _, _ in rows]) if rows else len("Chapter")
    out = io.StringIO()
    out.write(f'{"Chapter":<{name_width}}      Chars      Words  Chars/Word\n')
    out.write("---------\n")
    for name, chars, words in rows:
        ratio = chars / words if words else 0.0
        out.write(f"{name:<{name_width}}{chars:>12}{words:>11}{ratio:>12.2f}\n")
    out.write("---------\n")
    total_ratio = total_chars / total_words if total_words else 0.0
    out.write(f"{'TOTAL:':<{name_width}}{total_chars:>12}{total_words:>11}{total_ratio:>12.2f}\n\n")
    return out.getvalue()


def print_diagnostics(diagnostics: list[Diagnostic], *, quiet: bool, aggregated: bool) -> None:
    if not diagnostics:
        return
    if aggregated:
        if quiet:
            for diag in diagnostics:
                if diag.level != "error":
                    continue
                if diag.detailed:
                    sys.stderr.write(f"[ERROR] {diag.text}\n\n{diag.detailed}\n")
                else:
                    sys.stderr.write(f"[ERROR] {diag.text}\n")
            return
        sys.stderr.write("WARNING Crowbook exited successfully, but the following errors occurred:\n")
        for diag in diagnostics:
            prefix = "WARNING" if diag.level == "warning" else "ERROR"
            sys.stderr.write(f"{prefix} {diag.text}\n")
        return
    visible = [d for d in diagnostics if not quiet or d.level == "error"]
    if not visible:
        return
    if quiet:
        for diag in visible:
            prefix = "[ERROR]"
            if diag.detailed:
                sys.stderr.write(f"{prefix} {diag.text}\n\n{diag.detailed}\n")
            else:
                sys.stderr.write(f"{prefix} {diag.text}\n")
        return
    sys.stderr.write("WARNING Crowbook exited successfully, but the following errors occurred:\n")
    for diag in visible:
        prefix = "WARNING" if diag.level == "warning" else "ERROR"
        if diag.detailed:
            sys.stderr.write(f"{prefix} {diag.text}\n\n{diag.detailed}\n")
        else:
            sys.stderr.write(f"{prefix} {diag.text}\n")


def escape_json(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"')


def escape_tex(text: str) -> str:
    return (
        text.replace("\\", "\\textbackslash{}")
        .replace("&", "\\&")
        .replace("%", "\\%")
        .replace("$", "\\$")
        .replace("#", "\\#")
        .replace("_", "\\_")
        .replace("{", "\\{")
        .replace("}", "\\}")
        .replace("~", "\\textasciitilde{}")
        .replace("^", "\\textasciicircum{}")
    )


def tex_lang(lang: str) -> str:
    return {
        "fr": "french",
        "de": "german",
        "es": "spanish",
        "it": "italian",
    }.get(lang, "english")


