fn render_pdf(book: &Book, output: &OutputPath) -> Result<Vec<Diagnostic>, String> {
    let tex = render_tex_document(book);
    let temp_root = env::temp_dir().join(format!("crowbook-cleanroom-{}", pid_stamp()));
    fs::create_dir_all(&temp_root).map_err(|_| PDF_COMMAND_ERROR.to_string())?;
    let tex_path = temp_root.join("book.tex");
    fs::write(&tex_path, tex).map_err(|_| PDF_COMMAND_ERROR.to_string())?;
    let output_result = Command::new(book.options.get("tex.command").map(String::as_str).unwrap_or("xelatex"))
        .current_dir(&temp_root)
        .arg("book.tex")
        .output();
    let output_data = match output_result {
        Ok(data) => data,
        Err(_) => return Err(PDF_COMMAND_ERROR.to_string()),
    };
    if !output_data.status.success() {
        return Err(PDF_COMMAND_ERROR.to_string());
    }
    let pdf_path = temp_root.join("book.pdf");
    let bytes = fs::read(&pdf_path).map_err(|_| PDF_COMMAND_ERROR.to_string())?;
    let _ = write_binary_output(output, &bytes);
    Ok(Vec::new())
}

fn pid_stamp() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0)
}

