fn print_diagnostics(diagnostics: &[Diagnostic], quiet: bool, aggregated: bool) {
    if diagnostics.is_empty() {
        return;
    }
    if aggregated {
        if quiet {
            for diag in diagnostics.iter().filter(|d| d.level == Level::Error) {
                if let Some(detail) = &diag.detailed {
                    eprintln!("[ERROR] {}\n\n{}", diag.text, detail);
                } else {
                    eprintln!("[ERROR] {}", diag.text);
                }
            }
        } else {
            eprintln!("WARNING Crowbook exited successfully, but the following errors occurred:");
            for diag in diagnostics {
                match diag.level {
                    Level::Warning => eprintln!("WARNING {}", diag.text),
                    Level::Error => eprintln!("ERROR {}", diag.text),
                }
            }
        }
        return;
    }

    let visible: Vec<&Diagnostic> = if quiet {
        diagnostics.iter().filter(|d| d.level == Level::Error).collect()
    } else {
        diagnostics.iter().collect()
    };
    if visible.is_empty() {
        return;
    }
    if !quiet {
        eprintln!("WARNING Crowbook exited successfully, but the following errors occurred:");
        for diag in visible {
            match diag.level {
                Level::Warning => eprintln!("WARNING {}", diag.text),
                Level::Error => {
                    if let Some(detail) = &diag.detailed {
                        eprintln!("ERROR {}\n\n{}", diag.text, detail);
                    } else {
                        eprintln!("ERROR {}", diag.text);
                    }
                }
            }
        }
    } else {
        for diag in visible {
            if let Some(detail) = &diag.detailed {
                eprintln!("[ERROR] {}\n\n{}", diag.text, detail);
            } else {
                eprintln!("[ERROR] {}", diag.text);
            }
        }
    }
}

fn render_stats(book: &Book) -> String {
    let mut rows = Vec::new();
    let mut total_chars = 0usize;
    let mut total_words = 0usize;
    for chapter in &book.chapters {
        let raw_html = render_markdown_html(&chapter.content);
        let chars = plain_text_from_html(&raw_html).chars().count();
        let mut body_text = texts_in_tag(&raw_html, "p").join(" ");
        if body_text.is_empty() {
            body_text = plain_text_from_html(&raw_html);
        }
        let words = count_words(&body_text);
        total_chars += chars;
        total_words += words;
        rows.push((chapter.source_name.clone(), chars, words));
    }
    let name_width = rows
        .iter()
        .map(|(name, _, _)| name.len())
        .max()
        .unwrap_or(7)
        .max("Chapter".len());
    let mut out = String::new();
    let _ = writeln!(
        out,
        "{:<name_width$}      Chars      Words  Chars/Word",
        "Chapter",
        name_width = name_width
    );
    out.push_str("---------\n");
    for (name, chars, words) in &rows {
        let ratio = if *words == 0 { 0.0 } else { *chars as f64 / *words as f64 };
        let _ = writeln!(
            out,
            "{:<name_width$}{:>12}{:>11}{:>12.2}",
            name,
            chars,
            words,
            ratio,
            name_width = name_width
        );
    }
    out.push_str("---------\n");
    let total_ratio = if total_words == 0 {
        0.0
    } else {
        total_chars as f64 / total_words as f64
    };
    let _ = writeln!(
        out,
        "{:<name_width$}{:>12}{:>11}{:>12.2}",
        "TOTAL:",
        total_chars,
        total_words,
        total_ratio,
        name_width = name_width
    );
    out.push('\n');
    out
}

fn texts_in_tag(html: &str, tag: &str) -> Vec<String> {
    let mut out = Vec::new();
    let open = format!("<{tag}>");
    let close = format!("</{tag}>");
    let mut rest = html;
    while let Some(start) = rest.find(&open) {
        let after_open = &rest[start + open.len()..];
        if let Some(end) = after_open.find(&close) {
            out.push(plain_text_from_html(&after_open[..end]));
            rest = &after_open[end + close.len()..];
        } else {
            break;
        }
    }
    out
}

fn count_words(text: &str) -> usize {
    text.split_whitespace().count()
}

fn plain_text_from_html(html: &str) -> String {
    let mut out = String::new();
    let mut in_tag = false;
    for ch in html.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => in_tag = false,
            _ if !in_tag => {
                if ch == '\n' || ch == '\r' {
                    continue;
                }
                out.push(ch);
            }
            _ => {}
        }
    }
    html_unescape_basic(out.trim().to_string())
}

fn html_unescape_basic(text: String) -> String {
    text.replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

fn escape_html(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

fn escape_xml(text: &str) -> String {
    escape_html(text)
}

fn escape_json(text: &str) -> String {
    text.replace('\\', "\\\\").replace('"', "\\\"")
}

fn escape_tex(text: &str) -> String {
    text.replace('\\', "\\textbackslash{}")
        .replace('&', "\\&")
        .replace('%', "\\%")
        .replace('$', "\\$")
        .replace('#', "\\#")
        .replace('_', "\\_")
        .replace('{', "\\{")
        .replace('}', "\\}")
        .replace('~', "\\textasciitilde{}")
        .replace('^', "\\textasciicircum{}")
}

fn tex_lang(lang: &str) -> &'static str {
    match lang {
        "fr" => "french",
        "de" => "german",
        "es" => "spanish",
        "it" => "italian",
        _ => "english",
    }
}

fn iso_timestamp() -> String {
    // The real tool uses UTC. A deterministic fallback is enough for the reimplementation.
    "2026-08-09T00:00:00Z".to_string()
}

